window.ZZX_XCLINE={"meta":{"title":"时政线","src":"③27 届时政讲义（中心自研）","news":58,"tips":20,"principles":5,"templates":3},"basics":[{"k":"南北关系","t":"发展中国家与发达国家的关系。"},{"k":"南南合作","t":"发展中国家之间的经济合作关系。"},{"k":"东西问题","t":"和平问题；南北问题：发展问题。"},{"k":"战略合作伙伴关系","t":"是冷战结束后流行的一种国与国的关系。"},{"k":"","t":"我国“结伴不结盟”。"},{"k":"当今世界政治发展的趋势","t":"世界多极化"},{"k":"当今世界经济发展的趋势","t":"经济全球化"},{"k":"","t":"社会信息化、文化多样化"},{"k":"","t":"区域经济一体化（当代世界经济发展的一大特点）"}],"terms":[{"k":"单边主义","t":"举足轻重的特定大国，不考虑大多数国家和民众的愿望，单独或带头退出或挑战已制订或商议好了的维护国际性、地区性、集体性和平、发展、进步的规则和制度，并对全局或局部的和平、发展、进步有破坏性的影响和后果的行为与倾向。"},{"k":"保护主义","t":"以维护本国利益作为是否适用本国法律的依据；任何侵害了本国利益的人，不论其国籍和所在地域，都要受该国法律的追究，使其得到该国认为其应有的惩罚。在国际贸易中以保护国内产业为目的的经济政策。"},{"k":"多边主义","t":"国际上的事由大家共同商量着办，世界前途命运由各国共同掌握。国际社会应该按照各国共同达成的规则和共识来治理，而不能由一个或几个国家来发号施令。"}],"situation":[{"k":"经济全球化","t":"遭遇逆流、贸易保护主义、单边主义、反全球化势力上升，世界经济低迷，国际贸易和投资萎缩"},{"k":"世界多极化","t":"中、印等新兴发展中国家力量壮大，西方发达资本主义国家担心自身优势地位"},{"k":"信息社会化","t":"现代科技发展，信息化时代下各国各地区联系密切，人才竞争在国家竞争中作用越来越突出，各国重视科学技术发展与人才培养"},{"k":"文化多样化","t":"维护并促进文化多样性，尊重并平等对待各国文化，交流互鉴，取长补短。"},{"k":"世界安全","t":"传统安全与非传统安全问题增多(1) 传统安全：军事、政治、外交等方面的安全。(2) 非传统安全：军事、政治、外交冲突以外的其他对主权国家生存与发展构成重大威胁的安全问题，如经济安全、信息安全、生态安全、民族宗教冲突和高危传染性疾病。"},{"k":"大国关系","t":"相互尊重、公平正义、合作共赢"}],"tips":{"single":[{"y":"2026·15","stem":"2025 年10 月24 日十四届全国人大常委会第十八次会议表决通过了关于设立台湾光复纪念日的决定，以法律形式将10 月25 日设立为台湾光复纪念日。与“台湾光复纪念日”相关的历史事件是指1945 年10 月25 日","opts":[{"k":"A","t":"中国战区台湾省受降仪式在台北举行"},{"k":"B","t":"中、美、英等国发表《开罗宣言》和《波茨坦公告》"},{"k":"C","t":"日本无条件投降仪式在密苏里号战舰上举行"},{"k":"D","t":"日本天皇发布《终战诏书》"}],"ans":"","note":""},{"y":"2026·16","stem":"2025 年6 月16 日，联合国大会表决通过一项决议，宣布每年12 月4 日为“反对单边强制措施国际日”。其目的在于","opts":[{"k":"A","t":"敦促各国不采取、不破坏、不实行任何单边经济、金融或贸易措施"},{"k":"B","t":"促进国际社会联合起来反对美国发动的单边“关税战”"},{"k":"C","t":"彻底消除国际关系中的“单边主义”现象"},{"k":"D","t":"重新确立指导国家间和平关系的规范和原则"}],"ans":"","note":""},{"y":"2025·15","stem":"中国共产党第二十届中央委员会第三次全体会议于2024 年7 月15 日至18 日在北京举行。全会审议通过了《中共中央关于进一步全面深化改革、推动中国式现代化的决定》。全会提出，中国式现代化的基础性、战略性支撑是","opts":[{"k":"A","t":"高水平社会主义市场经济体制"},{"k":"B","t":"科学的宏观调控、有效的政府治理"},{"k":"C","t":"相互协调的物质文明和精神文明"},{"k":"D","t":"教育、科技、人才"}],"ans":"","note":""},{"y":"2025·16","stem":"2024 年9 月4 日至6 日，中非合作论坛北京峰会成功举行。习近平主席出席峰会开幕式并发表主旨讲话。本次峰会的重要成果之一是首次提出","opts":[{"k":"A","t":"支持非盟成为二十国集团成员"},{"k":"B","t":"欢迎更多非洲国家加入“金砖大家庭”"},{"k":"C","t":"在非洲启动建设农业发展与减贫示范村"},{"k":"D","t":"在非洲打造全球安全倡议\"合作示范区\""}],"ans":"","note":""},{"y":"2024·16","stem":"2023 年9 月18 日至26 日，第78 届联合国大会高级别周在联合国总部进行。相比以往，本届联大将更多目光投向了“全球南方”,议程主要着眼于“全球南方”国家提出的需求，讨论气候变化、主权债务减免、如何帮助陷入困境的国家实现联合国在繁荣、健康、发展、教育、性别平等方面的发展目标。中国作为世界上最大的发展中国家，在本届联大期间出席多场会议，表达“全球南方”天然成员的诉求与主张。“全球南方”国家的声音更响亮，是本届联大的亮点。这表明","opts":[{"k":"A","t":"全球南北对话的僵局已经破解"},{"k":"B","t":"“全球南方”国家在国际组织中的话语权和影响力占据了主导地位"},{"k":"C","t":"南方国家改变国际秩序游戏规则的议题成为了国际社会的普遍共识"},{"k":"D","t":"国际力量对比正在发生深刻变化，百年变局正在深入发展演进"}],"ans":"","note":""},{"y":"2023·16","stem":"2022 年11 月11 日，第二十五次中国-东盟领导人会议在柬埔寨首都金边举行,发表了中国和东盟国家就南海问题达成的又一份重要文件。这份文件是:","opts":[{"k":"A","t":"《中国和东盟国家外交部长关于全面有效落实〈南海各方行为宣言〉的联合声明》"},{"k":"B","t":"《落实〈南海各方行为宣言〉指导方针》"},{"k":"C","t":"《纪念〈南海各方行为宣言〉签署十周年联合声明》"},{"k":"D","t":"《纪念〈南海各方行为宣言〉签署二十周年联合声明》"}],"ans":"","note":""},{"y":"2022·16","stem":"《中华人民共和国反外国制裁法》于2021 年6 月10 日起施行。这是一部指向性、针对性颇强的专门法律，共有16 条。这部法律主要针对的是","opts":[{"k":"A","t":"西方某些大国近年来对我国的“贸易战”"},{"k":"B","t":"少数国家操纵国际组织挑起的“货币战”"},{"k":"C","t":"资本主义大国对社会主义国家的“新冷战”"},{"k":"D","t":"外国干涉中国内政的所谓“单边制裁”"}],"ans":"","note":""}],"multi":[{"y":"2021·16","stem":"2020 年中国国际服务贸易交易会（服贸会）于9 月4 日至9 日在北京成功举办。作为新冠疫情发生以来我国在线下举办的第一场重大国际经贸活动。本届服贸会受到全球瞩目，具有非同寻常的重大意义，也为世界经济注入了中国动力。本届服贸会的主题是","opts":[{"k":"A","t":"齐心协力携手前行"},{"k":"B","t":"全球服务互惠共享"},{"k":"C","t":"文化融合创新发展"},{"k":"D","t":"开放包容团结合作"}],"ans":"","note":""},{"y":"2026·32","stem":"2025 年2 月23 日，党的十八大以来第十三个指导“三农”工作的中央一号文件《中共中央国务院关于进一步深化农村改革扎实推进乡村全面振兴的意见》发布，此次是在历年中央一号文件中首次指出“因地制宜发展农业新质生产力”。“农业新质生产力”主要体现为","opts":[{"k":"A","t":"农村幸福宜居品质的持续提升"},{"k":"B","t":"农业传统生产领域科技的原创性突破"},{"k":"C","t":"先进生产要素的引入与集成"},{"k":"D","t":"农业向生物制造等领域跨越突破"}],"ans":"","note":""},{"y":"2026·33","stem":"中国历来重视发展与非洲国家的关系，对非洲国家重信守义。2025 年4 月24 日习近平总书记和来华进行国事访问的肯尼亚总统鲁托举行会谈并见证签署了20 项中肯合作文件，内容涵盖共建“一带一路”、经济贸易、高新科技、人文交流、新闻传播等领域。习近平主席明确指出，无论国际风云如何变幻，中非关系“不会变”的是","opts":[{"k":"A","t":"中非盟友关系不会变"},{"k":"B","t":"中国真实亲诚对非政策理念不会变"},{"k":"C","t":"中非患难与共、守望相助的初心不变"},{"k":"D","t":"中非合作共赢、共同发展的根本宗旨不变"}],"ans":"","note":""},{"y":"2025·32","stem":"2024 年6 月21 日，最高人民法院、最高人民检察院、公安部、国家安全部、司法部联合发布《关于依法惩治“台独”顽固分子分裂国家、煽动分裂国家犯罪的意见》，自发布之日起施行。其意义和作用体现在","opts":[{"k":"A","t":"明确了各类“台独”分裂行径的犯罪性质、刑事责任和惩处程序"},{"k":"B","t":"回应了两岸最大多数民众的诉求与期盼"},{"k":"C","t":"彰显了捍卫国家主权、统一和领土完整的坚定立场"},{"k":"D","t":"充实了反“台独”、反干涉的法律工具箱"}],"ans":"","note":""},{"y":"2025·33","stem":"金砖合作机制诞生于新兴市场和发展中国家群体性崛起的历史大潮中，牵动着世界格局演变和国际力量对比。成立18 年来，金砖不断发展壮大，金砖国家的人口占全球近一半，经济总量占世界比重超过三成，对世界经济增长贡献率超过50%。2024 年10 月22 日至24 日，金砖国家领导人第十六次会晤在喀山举行，决定邀请新一批国家成为金砖伙伴国。金砖机制持续壮大，金砖合作常葆活力，关键在于","opts":[{"k":"A","t":"以开放包容为襟怀"},{"k":"B","t":"以合作共赢为目标"},{"k":"C","t":"以公平正义为追求"},{"k":"D","t":"以构建同盟为路径"}],"ans":"","note":""},{"y":"2024·32","stem":"2023 年4 月3 日，学习贯彻习近平新时代中国特色社会主义思想主题教育工作会议在北京召开。会议强调，这次主题教育要牢牢把握“学思想、强党性、重实践、建新功”的总要求。要全面学习领会习近平新时代中国特色社会主义思想，全面系统掌握这一思想的基本观点、科学体系，把握好这一思想的世界观、方法论，坚持好、运用好贯穿其中的立场观点方法，不断增进对党的创新理论的","opts":[{"k":"A","t":"政治认同"},{"k":"B","t":"思想认同"},{"k":"C","t":"理论认同"},{"k":"D","t":"情感认同"}],"ans":"","note":""},{"y":"2024·33","stem":"在中方支持下，2023 年3 月6 日至10 日，沙特阿拉伯与伊朗在北京举行对话。3月10 日，中沙伊三方签署并发表联合声明，宣布沙伊双方同意恢复外交关系。这是党的二十大后中国外交的“大手笔”。中方推动沙伊握手言和的重要意义表现在","opts":[{"k":"A","t":"创造了调解冲突的新范式，为其他地区热点问题的解决提供了新思路"},{"k":"B","t":"使沙伊矛盾得以最终解决"},{"k":"C","t":"助力中东地区实现和平、稳定与安全"},{"k":"D","t":"为国际社会注入和平合作的正能量"}],"ans":"","note":""},{"y":"2023·32","stem":"2022 年8 月10 日，国务院台湾事务办公室、国务院新闻办公室发表《台湾问题与新时代中国统一事业》白皮书。该白皮书的发表有利于:","opts":[{"k":"A","t":"揭批“台独”分裂势力和外部势力勾连挑衅,企图损害中国主权和领土完整、阻挠破坏中国统一进程的恶劣言行"},{"k":"B","t":"最大限度地争取两岸同胞特别是台湾同胞与国际社会的理解和支持"},{"k":"C","t":"展现中国共产党和中国政府愿继续以最大诚意、尽最大努力争取和平统一的立场和态度"},{"k":"D","t":"提振全党全国各族人民矢志追求国家统一的精气神，增强岛内和海外反“独”促统力量的信心和勇气"}],"ans":"","note":""},{"y":"2023·33","stem":"2022 年11 月15 日，二十国集团领导人第十七次峰会在印度尼西亚巴厘岛举行。国家主席习近平出席并发表题为《共迎时代挑战·共建美好未来》的重要讲话，倡议推动:","opts":[{"k":"A","t":"更具竞争的全球发展"},{"k":"B","t":"更加包容的全球发展"},{"k":"C","t":"更加普惠的全球发展"},{"k":"D","t":"更有韧性的全球发展"}],"ans":"","note":""},{"y":"2022·32","stem":"2021 年5 月15 日7 时18 分，天问一号探测器成功着陆于火星乌托邦平原南部预选着陆区，我国首次火星探测任务着陆火星取得成功。其重要意义表现在","opts":[{"k":"A","t":"我国在行星探测领域进入世界先进行列"},{"k":"B","t":"我国首次自主执行了火星探测任务"},{"k":"C","t":"为探索宇宙奥秘、增进对火星演化的认知、了解生命起源作出了中国贡献"},{"k":"D","t":"我国航天事业发展取得了又一具有里程碑意义的进展"}],"ans":"","note":""},{"y":"2022·33","stem":"2021 年11 月16 日，中国国家主席习近平同美国总统拜登举行视频会晤，双方就事关中美关系发展的战略性、全局性、根本性问题以及共同关心的其他重要问题进行了充分、深入的沟通和交流。习近平强调，新时期中美相处应该坚持的原则是","opts":[{"k":"A","t":"相互尊重"},{"k":"B","t":"和平共处"},{"k":"C","t":"合作共赢"},{"k":"D","t":"结伴不结盟"}],"ans":"","note":""},{"y":"2021·32","stem":"2020 年6 月30 日，十三届全国人大常委会第二十次会议表决通过的《中华人民共和国香港特别行政区维护国家安全法》，是新形势下坚持和完善“一国两制”制度体系的标志性法律。其重大作用在于","opts":[{"k":"A","t":"确保国家主权在香港受到严格保护"},{"k":"B","t":"弥补香港国安方面的立法缺失"},{"k":"C","t":"有效应对各种反中乱港势力"},{"k":"D","t":"保障香港长治久安和长期繁荣稳定"}],"ans":"","note":""},{"y":"2021·33","stem":"2020 年11 月15 日，东盟10 国与中国、日本、韩国、澳大利亚和新西兰正式签署《区域全面经济伙伴关系协定》（RCEP），全球最大自贸区诞生。其重要意义主要体现在","opts":[{"k":"A","t":"开启了区域经济一体化新篇章"},{"k":"B","t":"全球贸易投资自由化、便利化取得压倒性优势"},{"k":"C","t":"将为区域乃至全球经济复苏注入新动能"},{"k":"D","t":"将更好地发挥中国作为亚太地区价值链中心节点的作用"}],"ans":"","note":""}]},"templates":[{"t":"当今世界的趋势和格局（世界背景）","d":"世界正处于大发展大变革大调整时期/当今世界正经历百年未有之大变局，政治多极化、经济全球化、社会信息化、文化多样化深入发展。地方保护主义、单边主义上升。经济全球化遭遇逆流，加剧了世界经济中的风险和不确定性，进而造成国际格局深刻演变。但是，和平与发展仍然是当今时代两大主题，世界多极化和经济全球化的时代潮流也不可能逆转。"},{"t":"万能意义类","d":"xxx 符合联合国宪章原则和国际法的基本准则，顺应了和平与发展的时代主题，有利于积极构建以合作共赢为核心的新型国际关系，推动构建人类命运共同体，推动建立国际政治经济新秩序。"},{"t":"中国贡献和措施（风景这边独好）","d":"中国贡献：中国始终是世界和平的建设者、全球发展的贡献者、国际秩序的维护者、公共产品的提供者，将继续以中国的新发展为世界提供新机遇。第一，经济贡献：中国始终是全球共同开放的重要推动者，是世界经济增长的稳定动力源，是各国拓展商机的活力大市场，是全球治理改革的积极贡献者。第二，政治贡献：中国坚定维护多边主义，坚定维护以联合国为核心的国际体系，坚定维护以国际法为基础的国际秩序。第三，生态贡献：中国以生态文明思想为指导，贯彻新发展理念，以经济社会发展全面绿色转型为引领，以能源绿色低碳发展为关键，坚持走生态优先、绿色低碳的发展道路。第四，文化贡献：中国提出全球文明倡议，推动文明交流互鉴。中国措施：第一，坚持和平发展道路，实行独立自主和平外交政策。推动建设新型国际关系，强调相互尊重、公平正义、合作共赢。第二，不断推动构建大国是关键、周边是首要、发展中国家是基础、多边是舞台的外交工作布局，积极发展全球伙伴关系。第三，秉持共商共建共享的全球治理观。第四，促进“一带一路”国际合作，推动建立以“持久和平、普遍安全、共同繁荣、开放包容、清洁美丽”为核心的人类命运共同体。"}],"principles":[{"t":"经济全球化（数字经济）","blocks":[{"h":"答题线索","d":"经济全球化、科技、产业革命、人工智能、大数据、云计算等"},{"h":"背诵要点","d":"重要性第一，经济全球化是世界经济发展的必然趋势，我们应顺应时代潮流，积极参与经济全球化。第二，经济全球化是一把双刃剑，我们要适应和引导好经济全球化，释放出更多正面效应。第三，面对机遇与挑战，正确的选择是充分利用一切机遇，合作应对一切挑战，引导经济全球化朝着更加开放、包容、普惠、平衡、共赢的方向发展。数字技术是世界科技革命和产业变革的先导力量，正在成为发展新质生产力的有力支撑，为全球经济增长注入新动能。只有发展数字经济，才能真正掌握国际竞争的主动权、掌控产业发展的主导权，打造经济社会发展新引擎、赢得未来发展新优势。"}]},{"t":"中美关系","blocks":[{"h":"答题线索","d":"中美在政治、经济、文化等问题上的观点、立场及其实质。以中美关系为例，如何处理应对大国关系。"},{"h":"背诵要点","d":"（1）背景：中美之间的差异实质是社会制度和外交政策的不同。中、美分别是最大的发展中国家和最大的发达国家，中美能否处理好彼此关系，攸关世界前途命运，是两国必须回答好的世纪之问。（2）措施：中美合则两利、斗则俱伤，合作是唯一正确的选择。努力将“中美建设性战略稳定关系”作为中美关系的战略指引。"}]},{"t":"多边主义","blocks":[{"h":"答题线索","d":"世界体系、国际治理、多边机制等等"},{"h":"背诵要点","d":"怎么看第一，多边主义是人类历经劫难后的共同选择，是联合国宪章宗旨和原则的集中体现。第二，面对全球化，挑战、责任与命运都是共同的，需要坚守多边主义的人间正道。第三，当前，单边主义不断抬头，捍卫多边主义更为紧迫和重要。第四，多边主义以维护世界和平、促进共同发展为目标，以维护公平正义、推动互利共赢为宗旨，以国际法和公认的国际关系基本准则为基础。"},{"h":"背诵要点","d":"怎么办措施：坚持多边主义，应当谋求共同发展；大国应体现责任担当；应当维护国际准则；应当树立共同体意识；应当坚持公平正义，以有效行动实现合作共赢。"}]},{"t":"联合国的地位和职责","blocks":[{"h":"设问方法","d":"为什么要坚持联合国理想，携手共创人类美好未来？or 如何理解四大全球倡议完全契合联合国的宗旨，且目标意义深远？"},{"h":"答题线索","d":"联合国、宗旨宪章、中国恢复联合国席位55 周年"},{"h":"背诵要点","d":"怎么看联合国在维护国际和平与安全、推动国际经济发展和建立国际经济新秩序、促进国际合作等方面作出的贡献和成就为国际社会所公认。当前形势下，无论是维护和平稳定，还是促进共同发展，联合国的作用只能加强，不能削弱，联合国的权威必须捍卫，不容侵犯。"},{"h":"背诵要点","d":"怎么办中国坚定维护以联合国宪章宗旨和原则为基石的国际关系基本准则。中国在联合国的框架下与各国合作处理国际事务，支持联合国发挥核心作用的核心机制，为世界和平与发展发挥更大作用。"}]},{"t":"四大全球倡议【中国方案】","blocks":[{"h":"设问方法","d":"如何理解四大全球倡议完全契合联合国的宗旨，且目标意义深远？"},{"h":"答题线索","d":"全球发展倡议，全球安全倡议，全球文明倡议，全球治理倡议，“四大全球倡议”"},{"h":"背诵要点","d":"“四大全球倡议”，丰富和发展了习近平外交思想，共同构成人类命运共同体大厦的“四大支柱”，为世界朝着构建人类命运共同体方向前行提供可行路径，引领新时代国际关系理论创新，是推动世界发展、安全、文明和治理的中国方案。“四大全球倡议”的核心理念同联合国宪章宗旨和原则一脉相承，展现了中国对联合国的坚定支持，反映了国际社会的共同心声，得到广泛支持。"},{"h":"设问方法","d":"四大全球倡议之间的关系"},{"h":"答题线索","d":"“四大全球倡议”为“四大赤字”把脉开方"},{"h":"背诵要点","d":"四大全球倡议各有侧重、并行不悖，构成更加完备、系统的中国方案，为破解和平赤字、发展赤字、安全赤字、治理赤字提供哲学基础与现实路径，归根结底是破解“领导力赤字”。国际局势动荡加剧、乱象频出之际，强权霸凌行径危害深重，严重冲击联合国等多边机制，世界渴望稳定性和方向感，迫切希望负责任的大国展现领导力、提供确定性。"},{"h":"设问方法","d":"全球治理倡议提出的意义"},{"h":"答题线索","d":"全球治理、改善完善全球治理"},{"h":"背诵要点","d":"全球治理倡议为解答“构建什么样的全球治理体系、如何改革完善全球治理”的时代命题，提供了中国方案。全球治理倡议的提出，有利于解决现行国际机制中全球南方代表性严重不足、权威性遭到侵蚀、有效性亟须提升的三大短板，也符合国际社会的普遍期待。"}]}],"news":[{"part":"国际时政","sec":"习总书记","title":"习近平会见爱尔兰总理马丁（1 月5 日）","stars":0,"date":"1月5日","body":"1 月5 日，国家主席习近平在北京人民大会堂会见来华进行正式访问的爱尔兰总理马丁。习近平指出，中国和爱尔兰都爱好和平、开放包容、自立进取，两国人民通过斗争赢得国家独立和民族解放，依靠几代人接续奋斗迈向现代化。2012 年两国建立互惠战略伙伴关系以来，双边贸易额翻了两番，相互投资均衡发展，两国人民双向奔赴，助力各自国家发展。相互尊重、平等相待、互利共赢是中爱关系长期稳定发展的宝贵经验，双方要共同传承和弘扬。中方愿同爱尔兰加强战略沟通，深化政治互信，扩大务实合作，为两国人民谋福祉，为中欧关系添动力。习近平强调，中爱双方要保持多层级、多领域友好交往，不断增进沟通和理解，照顾彼此核心利益和重大关切，巩固政治互信，筑牢双边关系政治基础。习近平指出，当今世界变乱交织，单边霸凌行径严重冲击国际秩序。各国都应尊重他国人民自主选择的发展道路，遵守国际法及联合国宪章宗旨和原则，大国尤应带头。中国和爱尔兰都支持多边主义，倡导国际公平正义，要在国际事务中加强协调合作，共同维护联合国权威，推动全球治理体系朝着更加公正合理的方向发展。中欧双方要着眼长远，坚持伙伴关系定位，客观理性看待和处理分歧，坚持合作共赢。爱尔兰下半年将担任欧盟轮值主席国，希望为中欧关系健康稳定发展发挥建设性作用。【时政选择题】国际关系","ex":{"stem":"（多选）1 月5 日，国家主席习近平在北京人民大会堂会见来华进行正式访问的爱尔兰总理马丁。自从两国建立互惠战略伙伴关系以来，双边贸易额翻了两番，相互投资均衡发展，两国人民双向奔赴，助力各自国家发展。中爱关系长期稳定发展的宝贵经验是","opts":[{"k":"A","t":"相互尊重"},{"k":"B","t":"共建同盟"},{"k":"C","t":"平等相待"},{"k":"D","t":"互利共赢"}],"ans":"ACD"}},{"part":"国际时政","sec":"习总书记","title":"习近平同韩国总统李在明举行会谈（1 月5 日）","stars":1,"date":"1月5日","body":"1 月5 日，国家主席习近平在北京人民大会堂同来华进行国事访问的韩国总统李在明举行会谈。习近平指出，中方始终将中韩关系置于周边外交重要位置，对韩政策保持连续性、稳定性。中方愿同韩方一道，牢牢把握友好合作方向，秉持互利共赢宗旨，推动中韩战略合作伙伴关系沿着健康轨道迈进，切实增进两国人民福祉，为地区乃至世界和平与发展正向赋能。习近平强调，中韩两国长期坚持“以和为贵”“和而不同”，超越社会制度和意识形态差异，相互成就、共同发展。双方应延续这一优良传统，不断增进互信，尊重各自选择的发展道路，照顾彼此核心利益和重大关切，坚持通过对话协商妥善解决分歧。习近平指出，当前世界百年变局加速演进，国际形势更加变乱交织。中韩在维护地区和平、促进全球发展方面肩负重要责任，有广泛利益交集，应当坚定站在历史正确一边，作出正确战略选择。80 多年前，中韩两国付出巨大民族牺牲，赢得抗击日本军国主义的胜利。今天更应携手捍卫二战胜利成果，守护东北亚和平稳定。作为经济全球化的受益者，中韩要共同反对保护主义，践行真正的多边主义，为推进平等有序的世界多极化、普惠包容的经济全球化作出贡献。【时政选择题】国际关系","ex":{"stem":"（多选）1 月5 日下午，国家主席习近平在北京人民大会堂同来华进行国事访问的韩国总统李在明举行会谈。习近平强调，中韩两国长期坚持“以和为贵”“和而不同”，超越社会制度和意识形态差异，相互成就、共同发展。中韩双方","opts":[{"k":"A","t":"应不断增进互信，尊重各自选择的发展道路"},{"k":"B","t":"照顾彼此核心利益和重大关切，坚持通过对话协商妥善解决分歧"},{"k":"C","t":"应携手捍卫二战胜利成果，守护东北亚和平稳定"},{"k":"D","t":"要共同反对保护主义，践行真正的多边主义，为推进世界多极化、经济全球化作出贡献"}],"ans":"ABCD"}},{"part":"国际时政","sec":"习总书记","title":"习近平会见加拿大总理卡尼（1 月16 日）","stars":1,"date":"1月16日","body":"1 月16 日上午，国家主席习近平在北京人民大会堂会见来华进行正式访问的加拿大总理卡尼。习近平指出，去年10 月，我们在韩国庆州会见，开启了中加关系转圜向好的新局面。双方就恢复和重启各领域合作深入探讨，取得积极成果。中加关系健康稳定发展符合两国共同利益，也有利于世界和平稳定和发展繁荣。双方要本着对历史、对人民、对世界负责任的态度，推进构建中加新型战略伙伴关系，推动中加关系迈入健康、稳定、可持续的发展轨道，更好造福两国人民。习近平就中加关系提出4 点意见。一要做相互尊重的伙伴。中加建交55 年来，两国关系历经风雨、跌宕起伏，留下宝贵历史经验和现实启示。中加两国虽然国情不同，但都应该尊重彼此主权和领土完整，尊重各自选择的政治制度和发展道路，坚持国与国正确相处之道。二要做共同发展的伙伴。中加经贸关系的本质是互利共赢，双方都从合作中受益。中国高质量发展、高水平开放将持续为中加合作提供新机遇、拓展新空间。双方要在促进合作上多做加法，在负面清单上多做减法，以更深入、更广泛的合作不断拉紧共同利益纽带。三要做彼此信任的伙伴。民心相通是最基础、最坚实、最持久的互联互通，双方要鼓励两国教育、文化、旅游、体育、地方等各界加强交流合作，便利人员往来，厚植民意基础。四要做相互协作的伙伴。一个分裂的世界无法应对人类面临的共同挑战，出路在于维护和践行真正的多边主义，推动构建人类命运共同体。中方愿同加方加强在联合国、二十国集团、亚太经合组织等框架内的沟通和协调，共同应对全球性挑战。【时政选择题】国际关系","ex":{"stem":"（多选）1 月16 日上午，国家主席习近平在北京人民大会堂会见来华进行正式访问的加拿大总理卡尼。习近平就中加关系提出的意见是","opts":[{"k":"A","t":"要做相互尊重的伙伴"},{"k":"B","t":"要做共同发展的伙伴"},{"k":"C","t":"要做彼此信任的伙伴"},{"k":"D","t":"要做相互协作的伙伴"}],"ans":"ABCD"}},{"part":"国际时政","sec":"习总书记","title":"习近平致电祝贺苏林当选越共中央总书记（1 月23 日）","stars":1,"date":"1月23日","body":"1 月23 日，中共中央总书记习近平致电苏林，祝贺他当选越共中央总书记。习近平在贺电中说，越共十三大以来，越南共产党坚定走符合越南国情的社会主义现代化道路，坚持和加强党的全面领导，团结带领越南人民在社会主义建设和革新事业中取得瞩目成就，越南国际地位和影响力不断提升。越共十四大成功召开，开启了越南民族发展新纪元，将鼓舞和促进世界社会主义运动发展。相信在以总书记同志为首的新一届越共中央领导下，越南共产党一定能够带领越南人民团结一心、砥砺奋进，推动越南党和国家事业取得新的更大成就，胜利完成越共十四大确定的各项目标任务。中越是社会主义友好邻邦，是具有战略意义的命运共同体。我十分珍视中越两党两国关系，愿同总书记同志一道，加强战略沟通，弘扬传统友谊，坚定推进社会主义事业，引领中越全面战略合作和命运共同体建设不断结出累累硕果，为两国人民带来更多福祉，为地区与世界和平稳定、发展繁荣作出积极贡献。【时政选择题】国际关系","ex":{"stem":"（多选）1 月23 日，中共中央总书记习近平致电苏林，祝贺他当选越共中央总书记。习近平在贺电中说，越共十三大以来，越南共产党坚定走符合越南国情的社会主义现代化道路，坚持和加强党的全面领导，团结带领越南人民在社会主义建设和革新事业中取得瞩目成就，越南国际地位和影响力不断提升。中越","opts":[{"k":"A","t":"组建了军事联盟"},{"k":"B","t":"是世代友好的战略合作盟友关系"},{"k":"C","t":"是具有战略意义的命运共同体"},{"k":"D","t":"是社会主义友好邻邦"}],"ans":"CD"}},{"part":"国际时政","sec":"习总书记","title":"习近平同巴西总统卢拉通电话（1 月23 日）","stars":1,"date":"1月23日","body":"1 月23 日上午，国家主席习近平同巴西总统卢拉通电话。习近平指出，2024 年，我和卢拉总统共同宣布将两国关系提升为携手构建更公正世界和更可持续星球的中巴命运共同体。一年多来，两国命运共同体建设顺利起势，发展战略对接不断走深走实，树立了全球南方国家团结合作的榜样。今年是中国“十五五”开局之年。中方将以高水平对外开放促进高质量发展，为中巴合作提供更多机遇。中方愿同巴方一道努力，全方位推进各领域互利合作，推动中巴关系得到更大发展，迎来更加美好的未来。习近平强调，当前国际形势动荡不安，中国和巴西作为全球南方重要成员，是维护世界和平稳定、改革完善全球治理的建设性力量，应当坚定站在历史正确一边，更好捍卫两国和全球南方共同利益，共同维护联合国核心地位和国际公平正义。中方愿始终做拉美和加勒比国家的好朋友、好伙伴，推进共建中拉命运共同体。【时政选择题】国际关系","ex":{"stem":"（多选）1 月23 日上午，国家主席习近平同巴西总统卢拉通电话。习近平指出，2024年，我和卢拉总统共同宣布将两国关系提升为携手构建更公正世界和更可持续星球的中巴命运共同体。习近平强调，当前国际形势动荡不安，中国和巴西","opts":[{"k":"A","t":"是维护世界和平稳定、改革完善全球治理的建设性力量"},{"k":"B","t":"是全球南方重要成员"},{"k":"C","t":"应当共同维护联合国核心地位和国际公平正义"},{"k":"D","t":"应当坚定站在历史正确一边，更好捍卫两国和全球南方共同利益"}],"ans":"ABCD"}},{"part":"国际时政","sec":"习总书记","title":"国家主席习近平同俄罗斯总统普京举行视频会晤（2 月4 日）","stars":1,"date":"2月4日","body":"2 月4 日下午，国家主席习近平在北京人民大会堂同俄罗斯总统普京举行视频会晤。习近平强调，今年是中国“十五五”开局之年，中方将更加积极主动扩大高水平对外开放，同包括俄罗斯在内的世界各国共享发展新机遇。今年也是中俄战略协作伙伴关系建立30 周年、《中俄睦邻友好合作条约》签署25 周年和“中俄教育年”启动之年。【时政选择题】国际关系","ex":{"stem":"（多选）2 月4 日下午，国家主席习近平在北京人民大会堂同俄罗斯总统普京举行视频会晤。习近平强调，今年是中国“十五五”开局之年，中方将","opts":[{"k":"A","t":"更加积极主动扩大高水平对外开放"},{"k":"B","t":"同包括俄罗斯在内的世界各国共享发展新机遇"},{"k":"C","t":"强化中俄同盟关系"},{"k":"D","t":"与俄方一道落实两国元首重要共识，加强战略沟通，深化务实合作"}],"ans":"ABD"}},{"part":"国际时政","sec":"习总书记","title":"国家主席习近平与美国总统特朗普举行会谈（5 月14 日）","stars":2,"date":"5月14日","body":"5 月14 日上午，国家主席习近平在北京人民大会堂同来华进行国事访问的美国总统特朗普举行会谈。习近平强调，中方致力于中美关系稳定、健康、可持续发展。我同特朗普总统赞同将构建“中美建设性战略稳定关系”作为中美关系新定位，将为未来3 年乃至更长时间的中美关系提供战略指引，相信会受到两国人民和国际社会的欢迎。“建设性战略稳定”应该是合作为主的积极稳定，应该是竞争有度的良性稳定，应该是分歧可控的常态稳定，应该是和平可期的持久稳定。“中美建设性战略稳定关系”不是一句口号，而应该是相向而行的行动。【时政】大国关系","ex":{"stem":"（多选）2026 年5 月14 日，国家主席习近平同美国总统特朗普举行会谈，提出构建“中美建设性战略稳定关系”，并指出“建设性战略稳定”应该是","opts":[{"k":"A","t":"合作为主的积极稳定"},{"k":"B","t":"竞争有度的良性稳定"},{"k":"C","t":"分歧可控的常态稳定"},{"k":"D","t":"和平可期的持久稳定"}],"ans":"ABCD"}},{"part":"国际时政","sec":"习总书记","title":"国家主席习近平同俄罗斯总统普京举行会谈（5 月20 日）","stars":2,"date":"5月20日","body":"5 月20 日上午，国家主席习近平在北京人民大会堂同来华进行国事访问的俄罗斯总统普京举行会谈。两国元首一致同意《中俄睦邻友好合作条约》继续延期。习近平指出，25 年前，中俄两国签署睦邻友好合作条约，以法律形式确立了长期睦邻友好、全面战略协作的制度基础，中俄关系从此实现跨越式发展。当前国际格局发生很大变化，世界面临倒退回丛林法则的危险。在此背景下，《中俄睦邻友好合作条约》的先进性、科学性和现实价值愈加凸显。中方支持《中俄睦邻友好合作条约》继续延期，将同俄方一道恪守条约精神，坚定推进中俄“背靠背”战略协作。5 月20 日下午，国家主席习近平同俄罗斯总统普京在北京人民大会堂共同出席“中俄教育年”开幕式。习近平强调，教育兴则国家兴，教育强则国家强。中俄要深化人才培养合作，共同培育国际顶尖人才队伍和国家战略科技力量，携手攻克前沿科学难题，助力两国创新发展；要践行文明互鉴理念，推动文明传承和教育治理经验交流，共同提高工作水平；要赓续传统友好情谊，进一步释放教育合作潜力，促进两国民众相知相亲，让青少年在深入交流中增进友谊，培育中俄世代友好的接班人。5 月20 日下午，国家主席习近平在北京人民大会堂同俄罗斯总统普京会谈后共同会见记者指出，在我和普京总统的共同战略引领下，中俄关系已经迈上新起点。双方要顺应和平、发展、合作、共赢的时代潮流，推动中俄关系实现更高质量发展。一是筑牢更高质量政治互信，坚定彼此战略支持。二是赋能更高质量互利合作，携手推进各自发展振兴。三是推进更高质量民心相通，厚植两国世代友好根基。四是开展更高质量国际协作，改革完善全球治理。5 月20 日晚，国家主席习近平在北京人民大会堂同俄罗斯总统普京举行茶叙。习近平指出，多年来，我同普京总统保持频密交往，共同引领中俄新时代全面战略协作伙伴关系持续走深走实，推动两国睦邻友好更加深入人心，开创了相互尊重、公平正义、合作共赢的新型大国关系范式，为变乱交织的世界持续注入宝贵的稳定性。【时政】大国关系【例题1】（多选）2026 年5 月20 日，国家主席习近平在同俄罗斯总统普京会谈时表示，在当前国际格局发生很大变化、世界面临倒退回“丛林法则”危险的背景下，《中俄睦邻友好合作条约》愈加凸显出哪些特性？A. 先进性B. 科学性C. 现实价值D. 排他性答案：ABC【新思想】教育强国【例题2】（单选）2026 年5 月20 日，国家主席习近平同俄罗斯总统普京共同出席“中俄教育年”开幕式。习近平在讲话中强调，教育兴则国家兴，教育强则国家强。这体现了A. 教育是民族振兴和社会进步的基石B. 教育是引领发展的第一动力C. 教育是解决我国一切问题的基础和关键D. 教育是中国特色社会主义的本质要求答案：A【时政】大国关系【例题3】（多选）2026 年5 月20 日晚，国家主席习近平同俄罗斯总统普京举行茶叙时指出，中俄关系开创了新型大国关系范式，为变乱交织的世界持续注入宝贵的稳定性。这一新型大国关系范式的内涵包括A. 相互尊重B. 公平正义C. 合作共赢D. 不冲突、不对抗答案：ABC","ex":null},{"part":"国际时政","sec":"习总书记","title":"习近平出席2026 世界人工智能大会暨人工智能全球治理高级别会议开幕式并发表主旨讲话（7 月17 日）","stars":0,"date":"7月17日","body":"习近平指出，当前，世界百年变局加速演进，新一轮科技革命和产业变革加速突破，全球人工智能技术创新进入前所未有的活跃期，既蕴含巨大机遇，也面临治理挑战。人类不得不直面时代之问：当机器开始思考，人类如何与之相处？当算法参与决策，安全如何保障？当技术挑战伦理，治理如何跟上？当鸿沟不断拉大，普惠如何实现？中方认为，各国应当秉持以人为本、向上向善理念，让人工智能成为促进共同繁荣、维护共同安全的一个重要动力源，携手构建公正合理的全球人工智能治理体系。习近平就此提出4 点意见：第一，坚持开放共赢，驱动创新发展。抓住难得的历史性机遇，鼓励开源开放、合作共享，全面促进人工智能科技创新、产业发展、场景应用，协同推进传统产业改造升级、新兴产业培育壮大、未来产业前瞻布局，让人工智能赋能千行百业。第二，强化风险意识，确保安全可控。高度重视人工智能引发的各类内生和衍生风险，推动构建法律法规、技术监测、风险预警、应急响应体系，筑牢安全底线，防范滥用恶用，确保人工智能始终处于人类控制之下。共同反对在人工智能领域泛化国家安全概念、把本国安全凌驾于他国安全之上的做法。第三，鼓励包容并蓄，促进文明互鉴。用全人类共同价值塑造人工智能的价值观，善用人工智能技术增进不同文明的理解和包容，促进不同文明交流互鉴，精心培育各美其美、美美与共的文明百花园。第四，倡导和衷共济，完善全球治理。践行真正的多边主义，切实发挥联合国的重要作用，加强人工智能发展战略、治理规则、技术标准的对接协调，早日形成具有广泛共识的全球治理框架，让这一前沿技术更好造福人类社会。帮助全球南方国家加强能力建设，弥合数智鸿沟，促进可持续发展，避免在人工智能领域造成新的历史不公。习近平强调，今年是中国“十五五”开局之年。“十五五”规划为未来5 年中国经济社会发展擘画蓝图，也为国际社会提供机遇清单。近年来，中国坚持有效市场和有为政府相结合，加强人工智能科技创新，积极推进“人工智能+”行动，培育各类主体共生共荣的健康生态，智能经济核心产业规模已经超过万亿元人民币，“中国智造”已成为中国式现代化的又一亮丽名片。同时，中国坚持发展和安全并重，不断完善相关法律法规、政策制度、应用规范、伦理准则，确保人工智能安全、可靠、可控。作为负责任大国，中国在人工智能领域始终致力于做国际公共产品的提供者，源源不断贡献中国方案。习近平指出，在各方共同努力下，世界人工智能合作组织在上海应运而生。这是中方响应全球南方呼声、团结国际社会积极推动人工智能发展和治理的重大举措，将成为人工智能发展史上的一个重要里程碑。为进一步支持全球人工智能发展、推进全球人工智能能力建设，未来5 年，中国将面向发展中国家提供5000 个人工智能专题研修培训名额；面向东盟、阿盟、非盟、拉共体、上合组织、金砖国家建设国际人工智能应用合作中心；推动气象智能预警方案“妈祖”在30 个国家落地应用。中国愿以更加开放的姿态、更加务实的行动、更加长远的目光，同各方一道把握和应对人工智能发展的机遇和挑战，携手共创人类社会更加美好的未来。【时政选择题】国际关系","ex":{"stem":"（多选）当前，世界百年变局加速演进，新一轮科技革命和产业变革加速突破，全球人工智能技术创新进入前所未有的活跃期，既蕴含巨大机遇，也面临治理挑战。习近平主席就此提出的意见分别是","opts":[{"k":"A","t":"坚持开放共赢，驱动创新发展"},{"k":"B","t":"强化风险意识，确保安全可控"},{"k":"C","t":"鼓励包容并蓄，促进文明互鉴"},{"k":"D","t":"倡导和衷共济，完善全球治理"}],"ans":"ABCD"}},{"part":"国际时政","sec":"习总书记","title":"习近平在埃及媒体发表署名文章（9 月1 日）","stars":0,"date":"9月1日","body":"9 月1 日，国家主席习近平在埃及发表题为《风雨同舟七十载，踔厉奋发新征程》的署名文章。习近平指出，中埃始终是和衷共济的亲密兄弟，中埃始终是合作共赢的可靠伙伴，中埃始终是友好互鉴的成功典范，中埃始终是平等互信的真诚朋友。中埃两国都处在发展振兴的关键阶段，中方愿同埃方一道，深化全面战略伙伴关系，推进中埃命运共同体建设，携手实现现代化。我们要增进互信，做传承友谊的楷模。我们要互利共赢，做携手发展的标杆。我们要各美其美，做文明交流的榜样。我们要并肩前行，做维护公平正义的先锋。我们要携手同心，做中阿、中非合作的引领者。","ex":null},{"part":"国际时政","sec":"习总书记","title":"习近平出席上海合作组织成员国元首理事会会议（9 月1 日）","stars":0,"date":"9月1日","body":"9 月1 日，国家主席习近平在比什凯克出席上海合作组织成员国元首理事会第二十六次会议。习近平同上海合作组织成员国领导人集体合影，随后出席元首理事会会议并发表题为《推动上海合作组织实现更高质量发展》的重要讲话。习近平指出，今年是上海合作组织成立25 周年。25 年来，上海合作组织走过不平凡历程。最重大的发展成就是一步步成为世界上幅员最广、人口最多、发展潜力巨大的新型区域合作组织；最宝贵的精神财富是开创性提出和始终遵循互信、互利、平等、协商、尊重多样文明、谋求共同发展的“上海精神”；最重要的合作经验是找到不结盟、不对抗、不针对第三方的正确共处之道，推动地区国家携手建设共同家园。习近平提出4 点主张：第一，坚持发展优先，开创共同繁荣的前景。第二，坚持安全为要，营造普遍安全的环境。第三，坚持以人为本，厚植世代友好的根基。第四，坚持对话协商，完善公平有序的治理。","ex":{"stem":"（多选）9 月1 日，国家主席习近平在比什凯克出席上海合作组织成员国元首理事会第二十六次会议。习近平提出的主张为","opts":[{"k":"A","t":"坚持发展优先，开创共同繁荣的前景"},{"k":"B","t":"坚持安全为要，营造普遍安全的环境"},{"k":"C","t":"坚持以人为本，厚植世代友好的根基"},{"k":"D","t":"坚持对话协商，完善公平有序的治理"}],"ans":"ABCD"}},{"part":"国际时政","sec":"习总书记","title":"习近平在比什凯克出席“上海合作组织+”会议（9 月1 日）","stars":0,"date":"9月1日","body":"9 月1 日下午，国家主席习近平在比什凯克出席“上海合作组织+”会议并发表题为《共同倡导平等有序的世界多极化 实现更加公正合理的全球治理》的重要讲话。习近平指出，这次会议聚焦加强联合国作用、构建多极世界，彰显了上海合作组织改革完善全球治理的时代担当。习近平强调，中国作为负责任大国，积极倡导平等有序的世界多极化，主权平等、相互尊重是根本原则，均衡有序、遵守法治是必然要求，多边主义、对话协商是关键路径，互利共赢、普惠包容是发展方向。习近平就更好发挥上海合作组织作用提出3 点建议：第一，以“上合力量”驱动亚欧大陆繁荣共兴。第二，以“上合智慧”推动全球南方发展壮大。第三，以“上合行动”引领全球治理改革完善。【时政选择题】国际关系","ex":{"stem":"（多选）9 月1 日下午，国家主席习近平在比什凯克出席“上海合作组织+”会议并发表题为《共同倡导平等有序的世界多极化 实现更加公正合理的全球治理》的重要讲话。习近平就更好发挥上海合作组织作用提出的建议为","opts":[{"k":"A","t":"以“上合担当”守护亚欧大陆和平安宁"},{"k":"B","t":"以“上合力量”驱动亚欧大陆繁荣共兴"},{"k":"C","t":"以“上合智慧”推动全球南方发展壮大"},{"k":"D","t":"以“上合行动”引领全球治理改革完善"}],"ans":"BCD"}},{"part":"国际时政","sec":"习总书记","title":"习近平出席金砖国家领导人第十八次会晤第二阶段会议（9 月12-13 日）","stars":0,"date":"9月12日","body":"9 月13 日上午，国家主席习近平在新德里出席金砖国家领导人第十八次会晤第二阶段会议，并发表题为《筑牢金砖合作根基 壮大全球南方力量》的重要讲话。习近平强调，全球南方国家要共同捍卫国际法治，维护主权平等、不干涉内政、和平解决争端等国际关系基本准则，确保国际法和国际规则平等适用、不搞双重标准；要高举多边主义旗帜，维护联合国权威和作用，支持多边机构改革增效，推动世界贸易组织改革保持正确方向，改革完善国际金融架构，提高发展中国家代表性和发言权；要坚持以人民为中心的发展思想，推动落实联合国2030 年可持续发展议程；要携手推进安全治理，共同应对传统和非传统安全威胁，完善全球气候治理，加快形成具有广泛共识的全球人工智能治理框架、让新兴技术照亮共同繁荣之路。习近平就深化金砖合作提出5 项倡议：一是人工智能开源普惠倡议。二是贸易投资便利化倡议。三是数字产业合作倡议。四是智能制造合作倡议。五是科技育才倡议。【时政选择题】国际关系","ex":{"stem":"（多选）9 月13 日上午，国家主席习近平在新德里出席金砖国家领导人第十八次会晤第二阶段会议，并发表题为《筑牢金砖合作根基 壮大全球南方力量》的重要讲话。习近平就深化金砖合作提出的倡议为","opts":[{"k":"A","t":"人工智能开源普惠倡议"},{"k":"B","t":"贸易投资便利化倡议"},{"k":"C","t":"数字产业与智能制造合作倡议"},{"k":"D","t":"科技育才倡议"}],"ans":"ABCD"}},{"part":"国际时政","sec":"习总书记","title":"习近平抵达华盛顿对美国进行国事访问（9 月23 日）","stars":0,"date":"9月23日","body":"9 月23 日下午，国家主席习近平乘专机抵达华盛顿，应美国总统特朗普邀请，对美国进行国事访问。习近平指出，中国和美国都是伟大的国家，中国人民和美国人民都是伟大的人民。中美两国人民长期友好交往，双方利益深度交融，两国应该成为伙伴而不是对手，实现中华民族伟大复兴和让美国再次伟大，完全可以并行不悖、相互成就、造福世界。特朗普总统今年5 月访问中国时，我们同意构建中美建设性战略稳定关系，为未来中美关系发展作出战略指引。中美双方应该相向而行，推动形成合作为主、竞争有度、分歧可控、和平可期的稳定关系，走出一条新时代中美两个大国正确相处之道。","ex":null},{"part":"国际时政","sec":"习总书记","title":"习近平对美国进行国事访问，中美同意构建建设性战略稳定关系（9 月23-25","stars":3,"date":"9月23日","body":"日）9 月23 日至25 日，国家主席习近平应邀对美国进行国事访问。这是习近平时隔11 年再次对美国进行国事访问。两国元首在相互尊重的友好氛围中，就事关中美关系和世界大势的战略性、全局性问题坦诚深入交换意见。当地时间9 月24 日，习近平在白宫欢迎仪式上发表致辞，强调中美要加强沟通、真诚合作、和平共处。他指出，中美两个大国合则两利、斗则俱伤，中美不必讳言竞争，但竞争应该是良性的、有边界的，应该是你追我赶的赛跑，而不是你输我赢的角斗。中美双方必须守住不冲突、不对抗的底线，“修昔底德陷阱”是可以跨越的。两国元首同意共同构建“基于尊重、公平、对等的建设性战略稳定关系”。尊重，就是尊重彼此主权和领土完整，尊重各自选择的社会制度和发展道路，尊重对方核心利益和重大关切；公平，就是开展互利合作、协商处理分歧，不搞你输我赢的零和博弈，不追求单方面的绝对优势；对等，就是两国主权平等，没有高低之分，不搞霸道霸凌。此访期间，中美达成八点成果共识，涉及经贸、禁毒执法、人工智能、国际和地区事务等众多领域，包括相互支持对方办好亚太经合组织（APEC）领导人非正式会议和二十国集团（G20）领导人峰会，建立并推进贸易理事会等机制，达成“300 亿美元”对等降税安排，建立中美人工智能对话。习近平还宣布，未来5 年，中方将邀请10 万名美国青少年来华交流学习。今年5 月，两国元首在北京会晤，决定构建中美建设性战略稳定关系，确立了两国关系的新定位；此次华盛顿会晤进一步拓展了新定位的内涵，使新定位更加清晰可感。中美关系又站在新的历史起点上。【时政选择题】中国外交","ex":{"stem":"（多选）2026 年9 月23 日至25 日，国家主席习近平应邀对美国进行国事访问。下列关于此次访问的表述正确的有","opts":[{"k":"A","t":"中美两国合则两利、斗则俱伤"},{"k":"B","t":"两国元首同意共同构建“基于尊重、公平、对等的建设性战略稳定关系”"},{"k":"C","t":"双方达成八点成果共识，涉及经贸、禁毒执法、人工智能、国际和地区事务等领域"},{"k":"D","t":"中美两国主权平等，没有高低之分"}],"ans":"ABCD"}},{"part":"国际时政","sec":"习总书记","title":"全球发展倡议5 周年高级别对话会举行，习近平致贺信（9 月25 日）","stars":2,"date":"9月25日","body":"2026 年9 月25 日，全球发展倡议5 周年高级别对话会在纽约联合国总部举行，国家主席习近平向对话会致贺信。习近平指出，发展是人类社会的永恒主题，也是实现人民幸福的关键所在。5年前，我在联合国大会上提出全球发展倡议，就是为了推动国际发展合作，重振全球发展事业，助力加快落实联合国2030 年可持续发展议程。2021 年9 月，习近平主席在第七十六届联合国大会一般性辩论上提出全球发展倡议，呼吁加强国际合作，加快落实联合国《2030 年可持续发展议程》。倡议以“六个坚持”为主要内容，即坚持发展优先、坚持以人民为中心、坚持普惠包容、坚持创新驱动、坚持人与自然和谐共生、坚持行动导向。5 年来，在各方共同努力下，全球发展倡议广泛践行，合作项目在120 多个国家落地生根、开花结果，书写了共促发展、合作共赢的新篇章。目前，已有130 多个国家和国际组织支持参与倡议，88 个国家加入“全球发展倡议之友小组”，20 多家发展机构参与联合国倡议推进工作组，动员各类发展资金230 多亿美元，开展1800 余个合作项目。习近平指出，当前，世界百年变局加速演进，各国人民对实现发展的愿望更加强烈。作为最大发展中国家和全球南方一员，中国愿同各方一道，秉持以人民为中心的发展理念，携手推动全球发展倡议走深走实，将可持续发展目标的美好愿景转化为可感可及的现实图景。从全球发展倡议到全球安全倡议、全球文明倡议、全球治理倡议，四大全球倡议相互支撑、有机统一，共同构成推动构建人类命运共同体的重要行动框架。【时政选择题】全球治理","ex":{"stem":"（单选）2026 年9 月25 日，全球发展倡议5 周年高级别对话会在纽约联合国总部举行，习近平主席向对话会致贺信。全球发展倡议以“六个坚持”为主要内容，其首要内容是","opts":[{"k":"A","t":"坚持发展优先"},{"k":"B","t":"坚持以人民为中心"},{"k":"C","t":"坚持创新驱动"},{"k":"D","t":"坚持行动导向"}],"ans":"A"}},{"part":"国际时政","sec":"习总书记","title":"中多构建命运共同体，习近平提出非洲热点问题4 条原则（10 月13 日）","stars":1,"date":"10月13日","body":"10 月13 日，国家主席习近平在北京人民大会堂会见来华进行正式访问的多哥部长会议主席福雷，两国领导人宣布将双边关系定位提升为新时代中多命运共同体；10 月15 日，《中华人民共和国政府和多哥共和国政府关于构建新时代中多命运共同体的联合声明》发布。习近平就各方建设性参与非洲热点问题解决提出坚持非洲主导、维护公平正义、推动止戈为和、实行标本兼治4 条原则，为推动冲突通过政治与和平方式解决、维护和平稳定、加强全球南方国家合作提供了重要框架。中多友好合作堪称中非友好和南南合作的卓越范例。中方欢迎多哥用好零关税和输华产品“绿色通道”等举措，愿同多方加强新能源、数智等领域合作，助力多哥工业化进程。【时政选择题】中国外交","ex":{"stem":"（多选）2026 年10 月13 日，习近平在会见多哥部长会议主席福雷时，就各方建设性参与非洲热点问题解决提出4 条原则。这4 条原则包括","opts":[{"k":"A","t":"坚持非洲主导"},{"k":"B","t":"维护公平正义"},{"k":"C","t":"推动止戈为和"},{"k":"D","t":"实行单边制裁优先"}],"ans":"ABC"}},{"part":"国际时政","sec":"其余领导人","title":"王毅以视频方式出席联合国人权理事会第61 届会议高级别会议（2 月24 日）","stars":0,"date":"2月24日","body":"王毅表示，中方愿同各国一道，以落实全球治理倡议为契机，完善全球人权治理，促进国际人权事业健康发展。一要奉行主权平等，守护全球人权治理初心。必须坚持各国平等参与、平等决策、平等受益，推动建设公正合理包容的全球人权治理体系。二要遵守国际法治，筑牢全球人权治理根基。各国应共同维护不干涉别国内政这一“黄金法则”，对以人权名义操弄双重标准的言行坚决说不。三要践行多边主义，破解全球人权治理挑战。四要倡导以人为本，充实全球人权治理内涵。要将发展权置于多边人权议程更加突出位置，让人权进步可视可感可及。五要注重行动导向，提升全球人权治理效能。中国愿同国际社会协调行动，共同描绘全球人权事业新图景。【时政选择题】全球治理","ex":{"stem":"（单选）习近平主席提出全球治理倡议，以中国智慧引领全球人权治理的方向，已得到150 多个国家和国际组织支持响应。各国要遵守国际法治，筑牢全球人权治理根基。各国应共同维护的“黄金法则”是","opts":[{"k":"A","t":"不干涉别国内政"},{"k":"B","t":"维护盟友关系"},{"k":"C","t":"摒弃各种形式的殖民主义"},{"k":"D","t":"破解全球人权治理挑战"}],"ans":"A"}},{"part":"国际时政","sec":"其余领导人","title":"中方决定向伊朗、约旦、黎巴嫩、伊拉克四国提供紧急人道主义援助（3 月17 日）","stars":0,"date":"3月17日","body":"中国始终践行人类命运共同体理念，秉持国际主义和人道主义精神。当前战事对伊朗等地区国家人民造成深重人道主义灾难，中方对此表示同情，向相关国家人民表示慰问。中方决定向伊朗、约旦、黎巴嫩、伊拉克四国提供紧急人道主义援助，希望这有助于缓解当地民众面临的人道主义困境。中方将继续尽自己的努力促和止战，推动早日恢复地区和平稳定，避免人道主义危机进一步蔓延。【时政】人类命运共同体理念","ex":{"stem":"（单选）中方决定向伊朗、约旦、黎巴嫩、伊拉克四国提供紧急人道主义援助，希望这有助于缓解当地民众面临的人道主义困境。中方将继续尽自己的努力促和止战，推动早日恢复地区和平稳定，避免人道主义危机进一步蔓延。这体现了我国","opts":[{"k":"A","t":"坚持以联合国为中心的多边主义，维护世界各国的共同利益"},{"k":"B","t":"践行人类命运共同体理念，展现大国担当"},{"k":"C","t":"旨在扩大在中东地区的军事存在和地缘影响力"},{"k":"D","t":"坚持以意识形态划界支持盟友国家"}],"ans":"B"}},{"part":"国际时政","sec":"其余领导人","title":"国务院总理李强会见美国工商界代表（5 月14 日）","stars":1,"date":"5月14日","body":"5 月14 日下午，国务院总理李强在人民大会堂会见随同美国总统特朗普访华的美国工商界代表。李强指出，在变乱交织的当今世界，稳定显得更加珍贵，需要大家共同守护。一个稳定可预期的中美经贸关系符合两国和世界利益。中美经贸合作体量大，市场和产业联系广泛，双方加强合作既能促进互利共赢，也有利于全球经济增长。中美作为世界前两大经济体，应当相向而行，带头促进开放合作，妥善处理和管控分歧，维护好两国经贸关系，做全球的稳定性和建设性力量。一个稳定发展的中国经济将为包括美资企业在内的各国企业提供更多机遇。我们正在实施“十五五”规划，中国市场的规模性、成长性、稳定性都十分明显，新的需求加快释放，新的动能不断壮大，经济持续稳中向好，欢迎更多外国企业来华开拓市场、共享机遇。一个稳定开放的政策环境是中国政府长期不变的承诺。我们将坚持扩大高水平开放，一如既往为外资企业做好服务，不断改进完善各项政策、提升行政效率，充分听取意见诉求，积极帮助排忧解难，让企业能够安心规划未来、专注自身发展。【新思想】外资经济高水平开放","ex":{"stem":"（多选）国务院总理李强在会见美国工商界代表时指出，一个稳定可预期的中美经贸关系符合两国和世界利益，中国将继续扩大高水平对外开放。下列对我国“高水平对外开放”理解正确的有","opts":[{"k":"A","t":"坚持引进来和走出去并重，既欢迎外资企业来华，也支持本国企业参与国际竞争"},{"k":"B","t":"保持稳定开放的政策环境，为外资企业提供长期可预期的制度保障"},{"k":"C","t":"依托中国市场的规模性、成长性和稳定性，为各国企业提供更多机遇"},{"k":"D","t":"高水平对外开放应优先面向发达国家，对发展中国家可适当保留市场准入门槛"}],"ans":"ABC"}},{"part":"国际时政","sec":"其余领导人","title":"国家副主席韩正出席2026 年全球贸易投资促进峰会开幕式并致辞（5 月18 日）","stars":1,"date":"5月18日","body":"5 月18 日，国家副主席韩正在北京出席2026 年全球贸易投资促进峰会开幕式并致辞。韩正提出4 点建议，一是共同营造开放合作的国际经济环境，坚定维护多边主义和开放合作，持续推动全球贸易投资自由化便利化。二是共同塑造创新发展新优势，充分发挥新技术的驱动和赋能作用，让科技创新成果更好造福各国人民。三是共同提升产业链供应链韧性，加强产业协同、技术交流和标准对接。四是共同推动全球经济治理体系改革，积极落实全球治理倡议，坚持共商共建共享，坚定维护以世贸组织为核心、以规则为基础的多边贸易体制。全球贸易投资促进峰会由中国贸促会主办，已连续举办5 届。本届峰会主题为“向新而行链接未来”。【新思想】高质量发展","ex":{"stem":"（多选）2026 年5 月18 日，国家副主席韩正在北京出席2026 年全球贸易投资促进峰会开幕式并致辞。他指出，当前世界百年变局加速演进，各国应携手应对挑战。关于我国主张下列表述正确的是","opts":[{"k":"A","t":"坚定维护多边主义和开放合作，促进全球贸易投资自由化便利化"},{"k":"B","t":"坚持创新驱动发展，致力于让科技创新成果惠及世界各国人民"},{"k":"C","t":"倡导加强国际产业协同与标准对接，共同维护全球产业链供应链稳定畅通"},{"k":"D","t":"积极参与全球经济治理体系改革，坚定维护以世贸组织为核心的多边贸易体制"}],"ans":"ABCD"}},{"part":"国际时政","sec":"其余领导人","title":"中共中央政治局委员、中央外办主任王毅在新德里出席金砖国家安全事务高级代表会议","stars":0,"date":"","body":"（6 月23 日）王毅表示，金砖国家合作已走过20 个春秋，日益成为世界上维护和平、促发展、守正义的中坚力量。面对当前国际格局发生的复杂深刻变化，中方愿同金砖国家一道，共同应对人类社会面临的紧迫挑战，共同坚守世界历史演进的正确方向。一是以金砖担当捍卫国际秩序。要高举多边主义旗帜，坚定捍卫联合国宪章宗旨和原则，旗帜鲜明反对单边主义、保护主义。作为全球南方第一方阵，金砖国家要带头说公道话、办公道事，提高在国际事务中的地位和作用。二是以金砖共识破解安全困局。要倡导共同、综合、合作、可持续的安全观，坚定推动热点问题的政治解决，积极探讨对话协商解决争端的有效方式。三是以金砖行动应对全球性挑战。要坚决打击一切形式恐怖主义，旗帜鲜明反对外空军事化，有力应对全球能源和粮食安全挑战，加强战略性矿产资源合作，团结应对非洲埃博拉疫情。四是以金砖智慧完善新兴领域治理。要密切防范人工智能风险，规范人工智能发展方向，支持以联合国为主渠道推进全球网络空间和数字治理。王毅表示，金砖的活力在于平等互利，金砖的力量在于团结互助。中方明年将担任金砖轮值主席国，愿同金砖伙伴一道，积极践行习近平主席提出的四大全球倡议，以发展促繁荣、以安全保稳定、以文明增互信、以治理求公正，共同开辟和平与繁荣的未来。","ex":null},{"part":"国际时政","sec":"其余领导人","title":"45 个国家共同发布《世界职业技术教育标准框架》（《北京协议》）（10 月17 日）","stars":0,"date":"10月17日","body":"10 月17 日，《世界职业技术教育标准框架》（《北京协议》）在2026 年世界职业技术教育发展大会闭幕式上由45 个国家共同发布。这是我国牵头推动研制形成的首个国际职业教育标准。协议将推动经济繁荣与社会进步、服务人的全面发展、拓宽社会公平通道、深化职业技能互学互鉴、积极应对未来挑战作为职业教育共同的价值追求。协议倡议完善职业学校办学体系、构建全民终身教育培训体系、产教协同建设教材、校企合作打造教师队伍、按岗位实际要求开展实习实训、人工智能赋能教育教学改革等育人体系，并提出相应治理、保障、行动路径。【时政选择题】教育强国","ex":{"stem":"（单选）2026 年10 月17 日，45 个国家共同发布《世界职业技术教育标准框架》（《北京协议》）。关于该协议，下列说法正确的是","opts":[{"k":"A","t":"它是我国牵头推动研制形成的首个国际职业教育标准"},{"k":"B","t":"它是第一个由联合国教科文组织制定的职业教育标准"},{"k":"C","t":"它仅面向成员国内部使用，不对外发布"},{"k":"D","t":"它主张以人工审核取代人工智能赋能教育教学改革"}],"ans":"A"}},{"part":"国际时政","sec":"其余领导人","title":"李强出席上海合作组织成员国政府首脑（总理）理事会第二十五次会议（10 月19 日）","stars":0,"date":"10月19日","body":"10 月19 日至20 日，上海合作组织成员国政府首脑（总理）理事会第二十五次会议在塔吉克斯坦杜尚别举行，国务院总理李强出席会议并发表讲话。李强指出，今年是上海合作组织成立25 周年，也是落实上合组织未来10 年发展战略的开局之年。习近平主席在9 月比什凯克峰会上指出，站在关乎人类前途命运的十字路口，上海合作组织应该勇担历史责任，主动引领历史航向。李强强调，上合组织应当持续弘扬“上海精神”，既致力于地区稳定繁荣，也为世界共同发展贡献力量。中方愿同各方加强协调，尽快完成“四个安全中心”建章立制，做实做强合作项目，推动上合组织实现更高质量发展。【时政选择题】中国外交","ex":{"stem":"（单选）2026 年10 月19 日至20 日，上海合作组织成员国政府首脑（总理）理事会第二十五次会议举行。关于本次会议，下列说法正确的是","opts":[{"k":"A","t":"会议在塔吉克斯坦杜尚别举行，今年是上海合作组织成立25 周年"},{"k":"B","t":"会议在哈萨克斯坦比什凯克举行，今年是上合组织成立20 周年"},{"k":"C","t":"会议通过了上合组织未来5 年发展战略"},{"k":"D","t":"习近平主席出席会议并发表重要讲话"}],"ans":"A"}},{"part":"两会","sec":"两会","title":"全国政协十四届四次会议在京开幕（3 月4 日）","stars":0,"date":"3月4日","body":"王沪宁表示，2025 年是中国式现代化进程中具有重要意义的一年。面对错综复杂的国际形势和艰巨繁重的国内改革发展稳定任务，以习近平同志为核心的中共中央团结带领全党全国各族人民，迎难而上、奋力拼搏，统筹国内国际两个大局，顺利完成全年经济社会发展主要目标，“十四五”圆满收官，我国经济实力、科技实力、国防实力、综合国力跃上新台阶，中国式现代化迈出新的坚实步伐。中共二十届四中全会胜利召开，擘画了“十五五”发展蓝图。王沪宁总结了过去一年来人民政协工作。他说，政协全国委员会及其常务委员会坚持以习近平新时代中国特色社会主义思想为指导，深刻领悟“两个确立”的决定性意义，增强“四个意识”、坚定“四个自信”、做到“两个维护”，认真贯彻落实中共二十大和二十届历次全会精神，贯彻落实习近平总书记关于加强和改进人民政协工作的重要思想和在庆祝中国人民政治协商会议成立75 周年大会上的重要讲话精神，坚持党的领导、统一战线、协商民主有机结合，坚持人民政协性质定位，坚持围绕中心、服务大局，充分发挥专门协商机构作用。坚持中国共产党的全面领导和党中央集中统一领导，自觉践行“两个维护”；学习宣传贯彻中共二十届四中全会精神，聚焦“十五五”规划制定建言献策；重视发挥专门委员会基础性作用和界别特色作用，提高专门协商机构效能；开展深入贯彻中央八项规定精神学习教育，营造风清气正、干事创业的良好氛围，各项工作取得新成效。王沪宁表示，2026 年是“十五五”开局之年，人民政协要坚持以习近平新时代中国特色社会主义思想为指导，深入贯彻中共二十大和二十届历次全会精神，认真落实中共二十届四中全会部署，贯彻落实习近平总书记关于加强和改进人民政协工作的重要思想，坚持和完善中国共产党领导的多党合作和政治协商制度，坚持人民政协性质定位，坚持团结和民主两大主题，坚持聚焦党和国家中心任务履职尽责，组织参加人民政协的各党派团体和各族各界人士，为实现“十五五”良好开局广泛凝聚人心、凝聚共识、凝聚智慧、凝聚力量。","ex":null},{"part":"两会","sec":"两会","title":"十四届全国人大四次会议在京开幕（3 月5 日）","stars":0,"date":"3月5日","body":"1.国务院总理李强代表国务院向大会作政府工作报告李强在报告中指出，2025 年是很不平凡的一年。面对国内外形势深刻复杂的变化，以习近平同志为核心的党中央团结带领全国各族人民迎难而上、奋力拼搏，坚定不移贯彻新发展理念、推动高质量发展，统筹国内国际两个大局，全年经济社会发展主要目标任务顺利完成，“十四五”圆满收官，中国式现代化迈出新的坚实步伐。李强在报告中指出，我们深入学习贯彻习近平新时代中国特色社会主义思想，全面贯彻落实党的二十大和二十届历次全会精神，按照党中央决策部署，一年来主要做了以下工作：一是实施更加积极有为的宏观政策，着力稳定经济运行；二是坚持创新驱动发展，建设现代化产业体系；三是进一步深化改革开放，畅通国民经济循环；四是统筹推进新型城镇化和乡村全面振兴，促进城乡区域协调发展；五是切实抓好民生保障，积极发展社会事业，出台稳就业支持政策，开展大规模职业技能提升培训行动，重点群体就业保持稳定；六是加快美丽中国建设，推动绿色低碳发展；七是持续加强政府建设，创新和完善社会治理。李强在报告中提出，今年发展主要预期目标是：经济增长4.5%－5%，在实际工作中努力争取更好结果；城镇调查失业率5.5%左右，城镇新增就业1200 万人以上；居民消费价格涨幅2%左右；居民收入增长和经济增长同步；国际收支基本平衡；粮食产量1.4 万亿斤左右；单位国内生产总值二氧化碳排放降低3.8%左右。李强在报告中提出，党中央对今年工作作出了全面部署，我们要深入贯彻落实，扎实做好各项工作：着力建设强大国内市场；加紧培育壮大新动能；加快高水平科技自立自强；持续深化重点领域改革；进一步扩大高水平对外开放；扎实推进乡村全面振兴；推动新型城镇化和区域协调发展；更大力度保障和改善民生；加快推动全面绿色转型；加强重点领域风险防范化解和安全能力建设。【时政选择题】民生建设","ex":{"stem":"（单选）2026 年两会通过《民族团结进步促进法》，对于全面推进民族团结进步事业，推动全国各族人民为以中国式现代化全面推进强国建设、民族复兴伟业团结奋斗，具有重大意义。推进民族团结进步的主线是","opts":[{"k":"A","t":"铸牢中华民族共同体意识"},{"k":"B","t":"巩固民族区域自治制度"},{"k":"C","t":"制定民族团结进步促进法"},{"k":"D","t":"依法治理民族事务"}],"ans":"A"}},{"part":"周年专题","sec":"周年专题","title":"庆祝中国共产党成立105 周年大会在北京人民大会堂隆重举行中共中央总书记、国家主席、中央军委主席习近平发表重要讲话（7 月1 日）","stars":0,"date":"7月1日","body":"习近平强调，105 年来，我们党团结带领全国各族人民不懈奋斗，创造了新民主主义革命、社会主义革命和建设、改革开放和社会主义现代化建设、新时代中国特色社会主义的伟大成就，书写了中华民族几千年历史上最恢宏的史诗。105 年不懈奋斗，从根本上改变了中国人民的前途命运，开辟了实现中华民族伟大复兴的正确道路，展示了马克思主义的强大生命力，深刻影响了世界历史进程，锻造了强大的中国共产党。我们党完全无愧为伟大光荣正确的党。习近平指出，中国共产党之所以能够在105 年奋斗中不断铸就辉煌，历史和人民之所以选择中国共产党，根本在于我们党具有其他政党和政治力量无可比拟的优秀特质。我们党矢志追求真理、始终把准前进方向，深深植根人民、始终拥有坚实根基，勇担历史使命、始终掌握战略主动，顺应发展潮流、始终走在时代前列，敢于善于斗争、始终保持必胜信心，注重强健自身、始终充满生机活力。我们要结合新的实际，把党的优秀特质不断发扬光大，确保党永远不变质不变色不变味，始终具有强大创造力凝聚力战斗力。习近平强调，实现新时代新征程党的使命任务，要求全体中国共产党人坚定信心、接续奋斗，不断创造无愧于时代和人民的新业绩。坚定信心、接续奋斗，必须坚持党的基本理论、基本路线、基本方略，坚持党的全面领导和党中央集中统一领导，深入贯彻新时代中国特色社会主义思想，坚定道路自信、理论自信、制度自信、文化自信，继往开来、守正创新，做到不畏浮云遮望眼、乘风破浪不迷航。必须紧紧依靠人民创造历史伟业，践行以人民为中心的发展思想，充分激发亿万人民的积极性主动性创造性，统筹推进“五位一体”总体布局、协调推进“四个全面”战略布局，完整准确全面贯彻新发展理念，加快构建新发展格局，扎实推动高质量发展。必须积极应对前进道路上的风险挑战，强化忧患意识、坚持底线思维，发扬斗争精神、增强斗争本领，更好统筹国内国际两个大局，统筹发展和安全。必须持续推动构建人类命运共同体，高举和平、发展、合作、共赢旗帜，弘扬全人类共同价值，推动落实全球发展倡议、全球安全倡议、全球文明倡议、全球治理倡议，为世界和平与发展注入更多正能量。必须持之以恒推进全面从严治党，全面贯彻新时代党建思想，健全全面从严治党体系，以党的政治建设为统领加强党的各方面建设，坚决打好反腐败斗争攻坚战持久战总体战，不断增强党的政治领导力、思想引领力、群众组织力、社会号召力。习近平强调，青年是实现中华民族伟大复兴的生力军。全党要重视青年、关心青年、支持青年，为青年成长成才创造条件。新时代中国青年要坚定不移听党话、跟党走，树立远大志向，勇担时代重任，在新征程上跑好历史接力赛，用青春铺路、让理想闪光。【时政选择题】党史党建","ex":{"stem":"（材料分析）习近平强调，青年是实现中华民族伟大复兴的生力军。结合材料，说明新时代中国青年应如何在新征程上跑好历史接力赛。答案：①坚定理想信念，坚定不移听党话、跟党走，把对马克思主义的信仰、对中国特色社会主义的信念作为立身之本。②树立远大志向，勇担时代重任，把个人理想融入国家发展大局，把青春奋斗融入党和人民事业。③立足岗位实干担当，在科技创新、乡村振兴、基层治理、卫国戍边等一线经风雨、见世面、壮筋骨，用实干书写无悔青春。④练就过硬本领，勤学苦读、刻苦钻研，努力成为堪当民族复兴重任的时代新人。⑤弘扬伟大建党精神，赓续红色血脉，锤炼品德修为，在实现中华民族伟大复兴的接力赛中跑好属于自己的这一棒，用青春铺路、让理想闪光。","opts":[],"ans":""}},{"part":"周年专题","sec":"周年专题","title":"纪念江泽民同志诞辰100 周年大会在北京人民大会堂隆重举行（8 月17 日）","stars":0,"date":"8月17日","body":"2026 年8 月17 日上午，纪念江泽民同志诞辰100 周年大会在北京人民大会堂隆重举行。中共中央总书记、国家主席、中央军委主席习近平发表重要讲话。习近平总书记全面回顾了江泽民同志光辉的一生和建立的丰功伟绩。江泽民同志是全党全军全国各族人民公认的享有崇高威望的卓越领导人，伟大的马克思主义者，伟大的无产阶级革命家、政治家、军事家、外交家，久经考验的共产主义战士，中国特色社会主义伟大事业的杰出领导者，党的第三代中央领导集体的核心，“三个代表”重要思想的主要创立者。习近平强调，江泽民同志留给我们的最可宝贵的财富，就是“三个代表”重要思想，这一重要思想是对马克思列宁主义、毛泽东思想、邓小平理论的继承和发展，反映了当代世界和中国的发展变化对党和国家工作的新要求，是加强和改进党的建设、推进我国社会主义自我完善和发展的强大理论武器。我们要继承江泽民同志的遗志，把新时代中国特色社会主义伟大事业不断推向前进，以实际行动纪念这位为党和人民建立了不朽功勋的卓越领导人。","ex":null},{"part":"周年专题","sec":"周年专题","title":"习近平在庆祝中华人民共和国成立77 周年招待会上发表重要讲话（9 月30 日）","stars":3,"date":"9月30日","body":"9 月30 日晚，庆祝中华人民共和国成立77 周年招待会在北京人民大会堂举行。中共中央总书记、国家主席、中央军委主席习近平出席招待会并发表重要讲话。习近平指出，77 年来，我们党团结带领人民不懈奋斗，创造了经济快速发展和社会长期稳定两大奇迹，实现了全面建成小康社会的第一个百年奋斗目标，正朝着全面建成社会主义现代化强国的第二个百年奋斗目标奋勇前进。习近平强调，今年以来，全党全国上下锐意进取、奋力拼搏，编制实施“十五五”规划，扎实推进各方面工作，我国经济顶压前行、向新向优、展现出强大韧性和活力，党和国家事业取得新进展新成效。我们要坚持稳中求进工作总基调，完整准确全面贯彻新发展理念，加快构建新发展格局，进一步深化改革开放，更好统筹发展和安全，推动经济持续向新向优向好发展，切实保障和改善民生，努力完成全年目标任务，实现“十五五”良好开局。习近平指出，我们要坚定不移贯彻“一国两制”、“港人治港”、“澳人治澳”、高度自治方针，支持香港、澳门更好融入和服务国家发展大局，保持长期繁荣稳定。要深化两岸交流合作，坚决打击“台独”分裂势力，反对外部势力干涉，推动两岸关系和平发展，推进祖国统一大业。习近平强调，我们要坚持独立自主的和平外交政策，推动落实四大全球倡议，推动构建人类命运共同体，为变乱交织的世界注入更多确定性和正能量。习近平指出，经过长期探索和实践，中国特色社会主义制度展现出巨大优势，我国国家治理体系和治理能力现代化水平不断提高，实现中华民族伟大复兴势不可挡。只要我们坚定信心、锚定目标，一步一步扎实往前走，成功就一定属于伟大的中国共产党、伟大的中国人民、伟大的中华人民共和国。【时政选择题】国家发展","ex":{"stem":"（单选）2026 年9 月30 日晚，庆祝中华人民共和国成立77 周年招待会在北京人民大会堂举行，习近平出席并发表重要讲话指出，77 年来，我们党团结带领人民不懈奋斗，创造的两大奇迹是","opts":[{"k":"A","t":"经济快速发展和社会长期稳定"},{"k":"B","t":"经济高速增长和社会和谐稳定"},{"k":"C","t":"科技自立自强和社会长期稳定"},{"k":"D","t":"经济高质量发展和社会全面进步"}],"ans":"A"}},{"part":"周年专题","sec":"周年专题","title":"烈士纪念日向人民英雄敬献花篮仪式在京隆重举行（9 月30 日）","stars":2,"date":"9月30日","body":"9 月30 日上午，烈士纪念日向人民英雄敬献花篮仪式在北京天安门广场隆重举行。习近平、李强、赵乐际、王沪宁、蔡奇、丁薛祥、李希、韩正等党和国家领导人出席仪式，同各界代表一起向人民英雄敬献花篮。仪式由中共中央政治局委员、北京市委书记尹力主持。10 时整，仪式正式开始，全场齐声高唱中华人民共和国国歌，随后肃立默哀，深切缅怀为中国人民解放事业和共和国建设事业英勇献身的烈士。方阵前，以中共中央、全国人大常委会、国务院、全国政协、中央军委等名义敬献的9 个大型花篮一字排开，缎带上书写的“人民英雄永垂不朽”格外醒目。习近平迈步上前，仔细整理花篮缎带，随后缓步绕行，瞻仰人民英雄纪念碑。今年是中国共产党成立105 周年、中国工农红军长征胜利90 周年。1936 年10 月，红军第一、第二、第四方面军先后在甘肃会宁、宁夏将台堡胜利会师，标志着历时两年、纵横十余省、行程二万五千里的长征胜利结束。长征的胜利，宣告了国民党反动派消灭中国共产党和红军的图谋彻底失败，实现了中国共产党和中国革命事业从挫折走向胜利的伟大转折。习近平总书记深刻指出，伟大长征精神，就是把全国人民和中华民族的根本利益看得高于一切，坚定革命的理想和信念，坚信正义事业必然胜利的精神；就是为了救国救民，不怕任何艰难险阻，不惜付出一切牺牲的精神；就是坚持独立自主、实事求是，一切从实际出发的精神；就是顾全大局、严守纪律、紧密团结的精神；就是紧紧依靠人民群众，同人民群众生死相依、患难与共、艰苦奋斗的精神。每一代人有每一代人的长征路，每一代人都要走好自己的长征路。【时政选择题】党史党建","ex":{"stem":"（多选）2026 年是中国共产党成立105 周年、中国工农红军长征胜利90 周年。9 月30日，烈士纪念日向人民英雄敬献花篮仪式在北京天安门广场隆重举行。下列关于红军长征的表述正确的有","opts":[{"k":"A","t":"长征的胜利标志着中国共产党和中国革命事业由挫折走向胜利的转折"},{"k":"B","t":"长征途中召开的遵义会议，挽救了党、挽救了红军、挽救了中国革命"},{"k":"C","t":"1936 年10 月，红军三大主力在甘肃会宁、宁夏将台堡胜利会师"},{"k":"D","t":"长征的胜利，宣告了国民党反动派消灭中国共产党和红军的图谋彻底失败"}],"ans":"ABCD"}},{"part":"周年专题","sec":"周年专题","title":"纪念中国工农红军长征胜利90 周年大会在京举行，习近平发表重要讲话（10月22 日）","stars":3,"date":"10月22日","body":"10 月22 日上午，纪念中国工农红军长征胜利90 周年大会在北京人民大会堂隆重举行。中共中央总书记、国家主席、中央军委主席习近平发表重要讲话，强调铭记历史方能开创未来，号召全党全军全国各族人民更加紧密地团结在党中央周围，大力弘扬伟大长征精神，接续奋斗、砥砺前行，把革命前辈开创的伟大事业不断推向前进，在新的长征路上奋力创造新的辉煌。习近平指出，从1934 年10 月至1936 年10 月，我们党领导红军第一、第二、第四方面军和第二十五军，进行了震撼世界、彪炳史册的伟大长征。红军长征纵横十余省，长驱二万五千里，跨越近百条江河，翻越皑皑雪山，穿过茫茫草地，进行600 余次战役战斗，粉碎上百万敌军围追堵截，宣告国民党反动派消灭中国共产党和红军的图谋彻底失败，胜利实现北上抗日的战略转移，成功开创了中国革命新局面。习近平深刻阐释了长征胜利蕴含的制胜之道：红军长征的伟大胜利之路，是依靠党的正确领导、坚定的革命意志、独立自主实事求是、广大人民群众支持走出来的。他强调，新征程上弘扬伟大长征精神、走好新的长征路，必须坚守党的理想信念宗旨，必须坚定不移推动高质量发展、不断满足人民日益增长的美好生活需要，必须勇于进行具有许多新的历史特点的伟大斗争，必须加快把人民军队建成世界一流军队，必须坚持党的领导、加强党的建设。【时政选择题】党史党建","ex":{"stem":"（材料分析）习近平总书记指出，每一代人有每一代人的长征路，每一代人都要走好自己的长征路。结合材料，说明新时代为什么必须弘扬伟大长征精神、走好新的长征路，以及如何走好新的长征路。答案：①从必然性看，实现中华民族伟大复兴是近代以来中华民族最伟大的梦想，前进道路上仍然面临许多具有新的历史特点的伟大斗争，风险挑战前所未有，必须从长征精神中汲取信仰的力量、真理的力量、人民的力量。②从精神传承看，要坚定理想信念，坚持人民立场，坚持实事求是，顾全大局、严守纪律、紧密团结，艰苦奋斗、不怕牺牲，把伟大长征精神转化为干事创业的实际行动。③从实践要求看，必须坚守党的理想信念宗旨；必须坚定不移推动高质量发展、不断满足人民日益增长的美好生活需要；必须勇于进行具有许多新的历史特点的伟大斗争；必须加快把人民军队建成世界一流军队；必须坚持党的领导、加强党的建设。④结语：每一代人都要走好自己的长征路，在新的长征路上奋力创造新的辉煌。","opts":[],"ans":""}},{"part":"经济板块","sec":"经济板块","title":"中央一号文件（2 月3 日）","stars":1,"date":"2月3日","body":"2026 年中央一号文件2 月3 日发布，这也是“十五五”首个中央一号文件，《中共中央国务院关于锚定农业农村现代化扎实推进乡村全面振兴的意见》提出锚定农业农村现代化，以推进乡村全面振兴为总抓手，以学习运用“千万工程”经验为引领，以改革创新为根本动力，提高强农惠农富农政策效能，守牢国家粮食安全底线，持续巩固拓展脱贫攻坚成果，提升乡村产业发展水平、乡村建设水平、乡村治理水平，努力把农业建成现代化大产业、使农村基本具备现代生活条件、让农民生活更加富裕美好，为推进中国式现代化提供基础支撑。这是党的十八大以来，第14 个指导“三农”工作的中央一号文件。【习思想选择题】乡村振兴","ex":{"stem":"（单选）2026 年中央一号文件2 月3 日发布，这也是“十五五”首个中央一号文件，《中共中央国务院关于锚定农业农村现代化扎实推进乡村全面振兴的意见》提出锚定农业农村现代化。文件提出，农业农村现代化的总抓手是","opts":[{"k":"A","t":"乡村振兴"},{"k":"B","t":"改革创新"},{"k":"C","t":"粮食安全"},{"k":"D","t":"“千万工程”经验"}],"ans":"A"}},{"part":"经济板块","sec":"经济板块","title":"“一船双潜器”模式进入业务化阶段（2 月18 日）","stars":0,"date":"2月18日","body":"2 月18 日，“蛟龙”号载人潜水器在西太平洋进行了2026 马年第一潜。此次西太平洋科学考察航次，由“深海一号”船搭载“蛟龙”号载人潜水器和无人遥控潜水器联合作业，标志着“一船双潜器”模式进入业务化阶段。【时政选择题】科技创新","ex":{"stem":"（单选）2 月18 日，“蛟龙”号载人潜水器在西太平洋进行了2026 马年第一潜。此次西太平洋科学考察航次，由“深海一号”船搭载“蛟龙”号载人潜水器和无人遥控潜水器联合作业，标志着","opts":[{"k":"A","t":"“一船双潜器”模式进入业务化阶段"},{"k":"B","t":"实现了我国天基太阳探测卫星跨越式突破"},{"k":"C","t":"中国成为继美、俄后第三个拥有自主卫星导航系统的国家"},{"k":"D","t":"中国成为世界上第三个能够独立开展载人航天活动的国家"}],"ans":"A"}},{"part":"经济板块","sec":"经济板块","title":"《求是》杂志发表习近平总书记重要文章《推动海洋经济高质量发展》（4 月16 日）","stars":1,"date":"4月16日","body":"文章强调，我国经略海洋、开发海洋历史悠久。新中国成立后，我们有序开发利用海洋。改革开放后，我国海洋经济进入加快发展期。推进中国式现代化，必须高效开发利用海洋，推动海洋经济高质量发展，走出一条具有中国特色的向海图强之路。文章指出，大的思路上，要更加注重创新驱动，尽快突破关键核心技术，推动海洋科技实现高水平自立自强；更加注重高效协同，坚持陆海统筹、山海联动，增强协同发展合力；更加注重产业更新，推动海洋传统产业转型升级，大力发展海洋新兴产业，积极培育海洋未来产业，建设现代海洋产业体系；更加注重人海和谐，统筹海洋资源开发和保护，建设可持续的海洋生态环境，形成人海良性互动的新格局；更加注重合作共赢，主动参与全球海洋治理，共同和平利用海洋能源资源，坚决维护我国领土主权和海洋权益。文章指出，具体工作上，要重点抓好6 个方面。第一，加强顶层设计和政策支持。编制“十五五”海洋经济发展规划，加大产业、科技、财税、金融等方面政策支持力度，鼓励引导社会资本积极参与发展海洋经济。第二，提高海洋科技自主创新能力。强化海洋战略科技力量，培育发展海洋科技领军企业和专精特新中小企业。第三，做强做优做大海洋产业。推动海上风电规范有序建设，发展现代化远洋捕捞，积极发展海洋生物医药、生物制品，打造海洋特色文化和旅游目的地，推进船舶和海洋工程装备产业高质量发展行动，加强“数字海洋”建设，推动海运业高质量发展。第四，加强主要海湾整体规划。有序推进沿海港口群优化整合，支持重点港口绿色化、数智化转型。第五，加强海洋生态环境保护。加强海洋环境风险源头防范，接续实施重点海域综合治理，积极推进海域分层立体利用，探索开展海洋碳汇核算。第六，深度参与全球海洋治理。加强全球海洋科研调查、防灾减灾、蓝色经济合作，推进“一带一路”国际港口联盟建设。【新思想】高质量发展","ex":{"stem":"（多选）我国经略海洋、开发海洋历史悠久。新中国成立后，我们有序开发利用海洋。改革开放后，我国海洋经济进入加快发展期。推进中国式现代化，必须高效开发利用海洋，推动海洋经济高质量发展，走出一条具有中国特色的向海图强之路。推动海洋经济高质量发展需要","opts":[{"k":"A","t":"加强顶层设计和政策支持"},{"k":"B","t":"提高海洋科技自主创新能力"},{"k":"C","t":"加强海洋生态环境保护"},{"k":"D","t":"深度参与全球海洋治理"}],"ans":"ABCD"}},{"part":"经济板块","sec":"经济板块","title":"中共中央办公厅、国务院办公厅印发《关于更高水平更高质量做好节能降碳工作的意见》☆（4 月22 日）","stars":0,"date":"4月22日","body":"4 月22 日，中共中央办公厅、国务院办公厅印发《关于更高水平更高质量做好节能降碳工作的意见》。文件明确，节能降碳是推进碳达峰碳中和、加快发展方式绿色转型的重要抓手，也是维护国家能源安全、推动产业提质升级的重要支撑，为经济社会发展全面绿色转型筑牢制度保障。《意见》明确总体工作要求，以习近平新时代中国特色社会主义思想为指导，贯彻党的二十大和二十届历次全会精神，完整准确全面贯彻新发展理念，坚持稳中求进工作总基调，坚持有效市场和有为政府相结合，统筹发展和安全，一以贯之坚持节约优先核心方针，将节能降碳贯穿经济社会发展全过程，严控能源消费不合理增长，提升能源资源利用效率，从源头削减碳排放。文件提出双向绿色转型路径。一是推动产业优化升级，严控高耗能、高排放项目，有序淘汰落后低效产能，依托数智、绿色技术改造传统产业，培育低碳新业态，推进零碳园区建设，探索“以绿制绿”发展模式。二是加快能源绿色转型，严控化石能源消费、推进减煤控油，稳步推动煤电有序调控，大力发展非化石能源、新型储能，构建新型电力系统，力争新增清洁能源发电量全面覆盖社会新增用电需求。聚焦五大重点领域精准发力，全面推进节能降碳。工业领域聚焦重点行业实施能效提升工程，推动园区资源循环与跨行业耦合提效；建筑领域推广超低能耗建筑，推进既有建筑改造和光伏一体化建设；交通领域优化运输结构，完善绿色交通设施，推广新能源运输工具；数字领域严控算力、基站等设施能效准入，提升绿色集约发展水平；公共机构推行节能改造与市场化节能模式，建设节约型机关。同时健全全链条监管体系，严格项目节能降碳审查评价，落实碳排放置换制度，对落实不力地区实施限批缓批。细化重点用能、碳排放单位精细化管理，建立常态化监测预警、专项督查与联合执法机制，压实主体责任。此外，从法治标准、政策金融、技术创新、基础能力四方面强化支撑保障，完善法律法规与能效标识体系，优化电价、税收、政府采购等激励政策，设立国家低碳转型基金，攻关核心节能技术，完善人才培养与统计制度。最后压实各级主体责任，将节能降碳成效纳入综合考核，倡导全民绿色低碳生活，深化节能降碳国际合作，全方位推动节能降碳工作提质增效。【新思想】生态文明建设","ex":{"stem":"（多选）2026 年4 月22 日，中共中央办公厅、国务院办公厅《关于更高水平更高质量做好节能降碳工作的意见》对外发布。文件指出，做好节能降碳工作的核心方针是（）","opts":[{"k":"A","t":"统筹发展和安全"},{"k":"B","t":"节约优先"},{"k":"C","t":"有效市场和有为政府相结合"},{"k":"D","t":"推动经济社会发展全面绿色转型"}],"ans":"B"}},{"part":"经济板块","sec":"经济板块","title":"习近平在河北雄安新区考察并主持召开深入推进雄安新区高质量建设和发展座谈会（4月23 日）","stars":0,"date":"4月23日","body":"习近平23 日在河北雄安新区考察，主持召开深入推进雄安新区高质量建设和发展座谈会并发表重要讲话。他强调，要牢牢把握雄安新区作为北京非首都功能疏解集中承载地的首要功能定位，保持战略定力和历史耐心，进一步解放思想、开拓思路、加强协调、凝聚合力，以改革创新为引领增强内生发展动力，以要素资源合理集聚为重点激发新区活力，努力建设新时代创新高地和推动高质量发展样板。【新思想】高质量发展","ex":{"stem":"（单选）2026 年4 月23 日，习近平总书记在河北雄安新区考察，主持召开深入推进雄安新区高质量建设和发展座谈会并发表重要讲话。习近平总书记强调，要牢牢把握雄安新区作为北京非首都功能疏解集中承载地的首要功能定位，努力建设新时代创新高地和推动高质量发展样板。推进雄安新区高质量建设旨在","opts":[{"k":"A","t":"以改革创新为引领，凝聚合力推动高质量发展"},{"k":"B","t":"探索以投资拉动经济增长的新模式"},{"k":"C","t":"将雄安新区的建设经验作为全国新区建设的统一模板"},{"k":"D","t":"推动雄安新区建设成为宜居宜业的现代化城市"}],"ans":"A"}},{"part":"经济板块","sec":"经济板块","title":"李强主持召开国务院常务会议（5 月9 日）","stars":1,"date":"5月9日","body":"国务院总理李强5 月9 日主持召开国务院常务会议，学习贯彻习近平总书记关于当前经济形势和经济工作的重要讲话、在加强基础研究座谈会上的重要讲话精神。会议指出，要切实把思想和行动统一到党中央对形势的科学判断上来，进一步增强信心，在应对变局中把握机遇，在攻坚克难中推动发展，巩固拓展经济稳中向好势头，努力实现“十五五”良好开局。宏观政策要在用好、用足上下功夫，坚持靠前发力，不断提升实施效能。做强国内大循环要在供需协同、联动升级上求突破，落实和完善服务业扩能提质举措，加强水网、新型电网、算力网、新一代通信网、城市地下管网、物流网等规划建设。民生保障要在稳就业、兜底线上多发力，做好教育、医疗、托育、“三农”等工作。要以更大力度、更实举措加强基础研究，把基础研究工作摆上重要日程，结合国家急迫需要和长远需求，明确主攻方向和重点领域，多措并举加大投入力度，注重营造良好科研生态。要有力有效应对风险挑战，持续推进房地产、地方政府债务、中小金融机构等领域风险化解，紧盯压实各方安全生产责任，坚决遏制重特大事故发生。【新思想】高质量发展","ex":{"stem":"（多选）国务院总理李强在国务院常务会议上强调，要“做强国内大循环”“加强基础研究”“民生保障要在稳就业、兜底线上多发力”。从推动高质量发展的角度看，下列表述正确的有","opts":[{"k":"A","t":"做强国内大循环需要供需协同，加强新型基础设施规划建设"},{"k":"B","t":"加强基础研究是实现科技自立自强的根基，需结合国家需求加大投入"},{"k":"C","t":"民生保障的重点是稳就业和兜底线，公共服务应由市场调节，政府无需干预"},{"k":"D","t":"防范化解重大风险是统筹发展和安全、推动高质量发展的重要保障"}],"ans":"ABD"}},{"part":"经济板块","sec":"经济板块","title":"神舟二十三号载人飞船发射升空（5 月24 日）","stars":1,"date":"5月24日","body":"我国瞄准5 月24 日23 时08 分发射神舟二十三号载人飞船，飞行乘组由朱杨柱、张志远、黎家盈3 名航天员组成，朱杨柱担任指令长，乘组1 名航天员将开展1 年期在轨驻留试验。这次任务是空间站应用与发展阶段第7 次载人飞行任务，也是载人航天工程第40 次飞行任务。任务主要目的是：与神舟二十一号乘组完成在轨轮换，继续开展空间科学与应用工作，实施航天员出舱活动及货物进出舱，进行舱外载荷和舱外设施设备安装与回收等任务，开展科普教育和公益活动，以及空间搭载试验，持续发挥空间站综合应用效益。【时政】航空航天成就","ex":{"stem":"（多选）2026 年5 月24 日23 时08 分，我国发射神舟二十三号载人飞船。关于此次任务的表述，正确的有","opts":[{"k":"A","t":"飞行乘组由朱杨柱、张志远、黎家盈三名航天员组成，朱杨柱担任指令长"},{"k":"B","t":"乘组中一名航天员将开展为期1 年的在轨驻留试验"},{"k":"C","t":"本次任务是载人航天工程第40 次飞行任务"},{"k":"D","t":"本次任务是空间站应用与发展阶段的首次载人飞行任务"}],"ans":"ABC"}},{"part":"经济板块","sec":"经济板块","title":"《求是》杂志发表习近平总书记重要文章《前瞻布局和发展未来产业》（5 月31 日）","stars":1,"date":"5月31日","body":"文章指出，要加强统筹谋划。未来产业具有前瞻性、战略性、颠覆性等特点，需要科学谋划、全局统筹。要把准发展方向，在量子科技、生物制造等领域聚焦发力、精准施策。科学论证技术路线，提升前沿技术战略预判能力。把握发展节奏，综合考虑国家战略需求、技术成熟程度、要素支撑条件等因素，因地制宜、错位发展。强化产业协同，坚持联动发展，推动未来产业同新兴产业、传统产业相得益彰。文章指出，要坚持以科技创新为引领。科技突破的程度，很大程度上决定未来产业发展的速度、广度、深度。要充分发挥新型举国体制优势，坚持“产业出题、科技答题”，大力提升科技支撑引领能力。加大重点领域关键核心技术攻关力度，加强基础研究战略性、前瞻性、体系化布局，加快科技成果转化应用。","ex":{"stem":"（多选）培育发展未来产业，对于我们抢占科技和产业制高点、牢牢把握发展主动权，对于发展新质生产力、建设现代化产业体系，对于提高人民生活品质、促进人的全面发展和社会全面进步，都具有重要意义。培育发展未来产业，要做到","opts":[{"k":"A","t":"推动未来产业完全取代传统产业"},{"k":"B","t":"大力提升科技支撑引领能力"},{"k":"C","t":"强化产业协同和联动发展"},{"k":"D","t":"加大重点领域关键核心技术攻关力度"}],"ans":"BCD"}},{"part":"经济板块","sec":"经济板块","title":"《求是》杂志发表中共中央总书记、国家主席、中央军委主席习近平的重要文章《一体推进教育科技人才发展》（6 月15 日）","stars":0,"date":"6月15日","body":"文章强调，教育、科技、人才是全面建设社会主义现代化国家的基础性、战略性支撑。建设教育强国、科技强国、人才强国具有内在一致性和相互支撑性。要增强系统观念，坚持教育优先发展、科技自立自强、人才引领驱动，统筹推进教育科技人才体制机制一体改革，实现科教兴国战略、人才强国战略、创新驱动发展战略有效联动，形成推动高质量发展的倍增效应。文章指出，要强化教育对科技和人才的支撑作用。科技创新靠人才，人才培养靠教育。要强化高水平研究型大学国家基础研究主力军和重大科技突破策源地作用，建立科技创新与人才培养相互支撑、带动学科高质量发展的有效机制，从国家战略需求中凝练重大科技问题，持续产出原创性、颠覆性科技创新成果。","ex":{"stem":"（单选）科技创新靠人才，人才培养靠教育，要一体推进教育强国、科技强国和人才强国建设。全面建设社会主义现代化国家的基础性、战略性支撑是","opts":[{"k":"A","t":"经济高质量发展"},{"k":"B","t":"坚持共产党的领导"},{"k":"C","t":"实现人自由而全面的发展"},{"k":"D","t":"教育、科技、人才"}],"ans":"D"}},{"part":"经济板块","sec":"经济板块","title":"国家科学技术奖励大会、中国科学院第二十二次院士大会和中国工程院第十八次院士大","stars":0,"date":"","body":"会、中国科学技术协会第十一次全国代表大会在北京人民大会堂隆重召开。中共中央总书记、国家主席、中央军委主席习近平出席大会并发表重要讲话。（7 月8 日）习近平强调，新一轮科技革命和产业变革深刻改变人类生产生活方式和世界发展格局。我们要适应新形势新要求，采取更加有力的措施，切实解决我国科技发展中存在的问题，全力抓好党中央关于科技事业各项部署的落实。习近平指出，要增强科技创新体系化攻关能力，提升国家创新体系整体效能。坚持“四个面向”战略导向，进一步加强科技战略规划、政策措施、重大任务、科研力量、资源平台、区域创新等方面统筹。完善国家重大科技创新任务部署和组织实施机制，强化科研基础条件自主保障。优化国家战略科技力量功能定位和布局，推动任务协同、资源共享、优势互补。加强对各层级科技工作的统筹指导，形成央地协同、区域联动的制度安排。习近平强调，要推动科技创新和产业创新深度融合，打通科技加速向现实生产力转化的通道。科技创新要突出应用导向，产业创新要提出科学问题。加强国家技术转移体系建设，打造多元化应用场景和高水平产业集群，促进自主研发技术产品推广应用和迭代升级。完善知识产权保护制度。构建同科技创新相适应的科技金融体制。习近平指出，科学的未来在青年，要优化科教协同育人机制，大力培养优秀青年科技人才。加大对科研人员支持力度，帮助解决实际困难，让他们潜心钻研、安身安心安业。注重挖掘和培养青少年兴趣特长、科学素养、实验能力，吸引更多具有科研潜质的青少年立志投身科技事业。习近平强调，要提高科技创新投入效能，实现投入规模增加与效能提升的统一。完善中央财政科技经费分配和管理使用机制，健全重大科技任务央地投入共担机制。改进科技计划管理，加强科技项目监督检查和绩效评估。引导企业增加研发投入，调动更多社会力量支持科技创新。习近平指出，要深化科技评价改革，用好科技评价指挥棒。项目评审、机构评估、人才评价都要强化创新能力、质量、实效、贡献导向。加快“破四唯”，持续深化科教界“帽子”治理。大力弘扬科学家精神，加强科研诚信建设，营造风清气正的科研生态。习近平强调，要加强科技伦理和安全治理，推动科技向上向善、安全可控、造福人民。完善政策制度、法律法规和治理规范，健全多方参与、协同共治的体制机制。明确重点领域伦理标准和指引，加强科技安全风险研判、监测预警和应急响应。深度参与全球科技治理，广泛宣介中国主张和中国方案。习近平指出，推动我国科技事业欣欣向荣，需要全党全社会共同努力。各级党委和政府要把科技工作摆上重要日程，树立和践行正确政绩观，真抓实干，久久为功，不断抓出新成效。中国科学院、中国工程院要团结全国科技界把握新一轮科技革命方向，勇攀世界科学高峰。中国科协要坚持探索创新，尽心尽力为科技工作者服务、为创新驱动发展服务、为提高全民科学素质服务、为党和政府科学决策服务。","ex":null},{"part":"经济板块","sec":"经济板块","title":"绿色算力（人工智能）大会（8 月22 日）","stars":0,"date":"8月22日","body":"2026 年8 月22 日，绿色算力（人工智能）大会在内蒙古自治区呼和浩特市开幕。本次大会以“共筑算电协同之路，共商词元经济新局，共创人工智能未来”为主题，集中发布多项绿色智算创新成果，正式启动数字服务出海平台，落地全国视频大模型算力基地。大会深入贯彻落实国家“东数西算”工程战略部署，充分发挥内蒙古清洁能源富集、气候冷凉的自然禀赋优势，推动算力基础设施绿色化、集约化、智能化发展。大会发布的绿色智算成果涵盖高效制冷、可再生能源利用、算网协同等关键技术领域，为全国算力产业低碳转型提供技术路径。数字服务出海平台的启动，标志着我国数字贸易国际化布局迈出关键步伐；全国视频大模型算力基地的落地，将有效支撑人工智能大模型训练推理需求，赋能千行百业数字化转型。本次大会是落实“双碳”目标、发展新质生产力的重要实践，对于优化全国算力资源配置、促进区域协调发展、建设数字中国具有重要推动作用。","ex":{"stem":"（多选）2026 绿色算力（人工智能）大会在呼和浩特成功举办，立足我国“东数西算”国家战略布局，聚焦绿色算力、人工智能融合发展，发布多项行业重磅成果，落地国家级算力基础设施平台，助力新质生产力发展与数字经济对外开放。本次大会落地、启动的重要成果有","opts":[{"k":"A","t":"全国视频大模型算力基地落地"},{"k":"B","t":"启动数字服务出海综合服务平台"},{"k":"C","t":"我国数字贸易国际化布局全面完成"},{"k":"D","t":"发布多项绿色算力、智算行业研究成果"}],"ans":"ABD"}},{"part":"政治板块","sec":"政治板块","title":"中共中央政治局常务委员会召开会议中共中央总书记习近平主持会议（1 月8 日）","stars":1,"date":"1月8日","body":"中共中央政治局常务委员会1 月8 日召开会议，听取全国人大常委会、国务院、全国政协、最高人民法院、最高人民检察院党组工作汇报，听取中央书记处工作报告。中共中央总书记习近平主持会议并发表重要讲话。会议指出，党中央听取全国人大常委会、国务院、全国政协、最高人民法院、最高人民检察院党组工作汇报和中央书记处工作报告，是坚持和完善党的领导制度体系，把党中央集中统一领导落实到国家治理各领域各方面各环节的重要举措。“十五五”时期，我国发展环境面临深刻复杂变化，工作任务艰巨繁重，要坚持好、运用好、发展好党的领导这一最大优势，为中国式现代化建设提供根本保证。会议强调，今年是中国共产党成立105 周年，是“十五五”开局之年。全国人大常委会、国务院、全国政协、最高人民法院、最高人民检察院党组要以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二十届历次全会精神，认真落实四中全会部署，坚持党中央集中统一领导，深刻领悟“两个确立”的决定性意义，增强“四个意识”、坚定“四个自信”、做到“两个维护”，始终在思想上政治上行动上同以习近平同志为核心的党中央保持高度一致，不折不扣把党中央各项决策部署落到实处。要锚定“十五五”时期经济社会发展的重大战略任务，统一意志、形成合力，共同推进各领域工作，努力实现良好开局。树立和践行正确政绩观，坚持为人民出政绩、以实干出政绩。加强党组自身建设，认真履行全面从严治党主体责任，切实增强自我革命的自觉性坚定性。【新思想选择题】全面从严治党","ex":{"stem":"（单选）“十五五”时期，我国发展环境面临深刻复杂变化，工作任务艰巨繁重，为中国式现代化建设提供根本保证的是","opts":[{"k":"A","t":"坚持以人民为中心"},{"k":"B","t":"党的领导"},{"k":"C","t":"树立和践行正确政绩观"},{"k":"D","t":"加强党组自身建设"}],"ans":"B"}},{"part":"政治板块","sec":"政治板块","title":"追授贺娇龙同志“新疆维吾尔自治区优秀共产党员”称号（1 月11 日）","stars":0,"date":"1月11日","body":"中共新疆维吾尔自治区委员会日前决定，追授贺娇龙同志“新疆维吾尔自治区优秀共产党员”称号。2026 年1 月11 日，她在博乐市执行农产品电商宣传拍摄任务时意外坠马，经全力抢救无效，于1 月14 日不幸离世。贺娇龙同志将一生奉献给兴边富民事业，为表彰先进、弘扬正气，自治区党委决定，追授贺娇龙同志“新疆维吾尔自治区优秀共产党员”称号，并号召广大党员干部向贺娇龙同志学习，树立和践行正确政绩观，主动顺应时代发展，学网、懂网、用网，积极探索数字经济与实体经济融合路径，推动新疆特色产业提质增效，始终把人民群众放在心中最高位置，用脚步丈量民情，以实干纾解民忧。【思修分析题、选择题】道德模范","ex":{"stem":"（多选）中共新疆维吾尔自治区委员会决定，追授贺娇龙同志“新疆维吾尔自治区优秀共产党员”称号。贺娇龙同志","opts":[{"k":"A","t":"树立和践行了正确的政绩观"},{"k":"B","t":"用脚步丈量民情，以实干纾解民忧"},{"k":"C","t":"学网、懂网、用网，积极探索数字经济与实体经济融合路径"},{"k":"D","t":"推动新疆特色产业提质增效，始终把人民群众放在心中最高位置"}],"ans":"ABCD"}},{"part":"政治板块","sec":"政治板块","title":"习近平在二十届中央纪委五次全会上发表重要讲话（1 月12 日）","stars":1,"date":"1月12日","body":"中共中央总书记、国家主席、中央军委主席习近平12 日在中国共产党第二十届中央纪律检查委员会第五次全体会议上发表重要讲话。他强调，要坚持和加强党的全面领导，以更高标准、更实举措推进全面从严治党，更加坚决有力地贯彻落实党中央重大决策部署，更加科学有效地把权力关进制度笼子，更加清醒坚定地推进反腐败斗争，为实现“十五五”时期目标任务提供坚强保障。习近平强调，贯彻落实党中央重大决策部署，是维护党中央权威和集中统一领导的根本要求，也是党和人民事业不断发展进步的重要历史经验。习近平指出，党的自我革命重在治权，把权力关进制度笼子是新时代全面从严治党的一项重要任务。习近平强调，腐败是党和国家事业发展进程中的拦路虎、绊脚石，反腐败是一场输不起也决不能输的重大斗争。习近平指出，纪检监察机关在推进党的自我革命、全面从严治党中责任重大、使命光荣，要坚定维护党的团结统一，坚定捍卫党的先进性纯洁性。12 日下午，李希代表中央纪律检查委员会常务委员会作题为《以更高标准、更实举措推进全面从严治党，为实现“十五五”时期目标任务提供坚强保障》的工作报告。【新思想选择题】全面从严治党","ex":{"stem":"（单选）中共中央总书记、国家主席、中央军委主席习近平12 日在中国共产党第二十届中央纪律检查委员会第五次全体会议上发表重要讲话。维护党中央权威和集中统一领导的根本要求是","opts":[{"k":"A","t":"党的自我革命"},{"k":"B","t":"把权力关进制度笼子"},{"k":"C","t":"捍卫党的先进性纯洁性"},{"k":"D","t":"贯彻落实党中央重大决策部署"}],"ans":"D"}},{"part":"政治板块","sec":"政治板块","title":"习近平在省部级主要领导干部学习贯彻党的二十届四中全会精神专题研讨班开班式上发表重要讲话☆（1 月20 日）","stars":0,"date":"1月20日","body":"中共中央总书记、国家主席、中央军委主席习近平在开班式上发表重要讲话强调，要把学习贯彻党的二十届四中全会精神不断引向深入，更好统一思想、凝心聚力，在党中央坚强领导下扎实做好各项工作，努力实现“十五五”良好开局。习近平指出，制定和实施五年规划是我们党治国理政一条重要经验，是中国特色社会主义制度一个重要政治优势，有利于实现党的领导，有利于集中力量办大事，有利于前瞻性把握战略问题，有利于保持事业连续性。在制定实施五年规划的长期实践中，我们党创造积累了丰富经验，包括坚持党中央集中统一领导，坚持从实际出发，坚持全国一盘棋，坚持发扬民主、集思广益，坚持规划法定原则等。我们要坚定制度自信，不断结合新的实际把这一优势发扬光大。习近平强调，建设现代化产业体系、实现产业体系整体跃升，是“十五五”时期的重要战略任务。各地区各行业要找准定位，坚持智能化、绿色化、融合化方向，发挥比较优势，形成上下游产业相互衔接、各展其长、同向发力的生动局面。要保持制造业合理比重，大力发展先进制造业。因地制宜发展新质生产力，推动科技创新和产业创新深度融合。要建设现代化基础设施。习近平指出，我国人口多、市场大、产业全、发展动能强，有条件加快构建新发展格局。要坚持以国内大循环为主体，正确处理消费和投资、需求和供给的关系，坚持惠民生和促消费、投资于物和投资于人紧密结合，努力提高国民经济循环质量和效率，让内需成为经济发展的主动力。要以做强国内大循环提升扩大高水平对外开放的自主性，以拓展国际循环增强国内改革发展的活力，努力实现内外联通、互促共进。习近平强调，经济发展和社会发展相辅相成，必须协调并进。要把改善民生作为促进社会发展的重点，在发展经济的同时稳步提高人民生活品质。要坚持党建引领，强化法治保障，夯实基层基础，切实提高社会治理水平。要统筹发展和安全，有效防范化解各类风险，切实维护国家安全和社会稳定。习近平指出，要坚持科学决策、民主决策、依法决策，编制好国家和地方“十五五”规划纲要及专项规划。地方规划和专项规划要与国家整体规划衔接好，体现国家整体规划的精神和要求，同时要因地因事制宜，把需要和可能统一起来，确保定了就做得到、能落地见效。【新思想、时政选择题】党的二十届四中全会","ex":{"stem":"（多选）省部级主要领导干部学习贯彻党的二十届四中全会精神专题研讨班20 日上午在中央党校（国家行政学院）开班。中共中央总书记、国家主席、中央军委主席习近平在开班式上发表重要讲话强调，制定和实施五年规划是我们党治国理政一条重要经验，是中国特色社会主义制度一个重要政治优势，有利于","opts":[{"k":"A","t":"实现党的领导"},{"k":"B","t":"集中力量办大事"},{"k":"C","t":"前瞻性把握战略问题"},{"k":"D","t":"保持事业连续性"}],"ans":"ABCD"}},{"part":"政治板块","sec":"政治板块","title":"中办印发《通知》在全党开展树立和践行正确政绩观学习教育（2 月23 日）","stars":0,"date":"2月23日","body":"近日，中共中央办公厅印发《关于在全党开展树立和践行正确政绩观学习教育的通知》。《通知》明确，要坚持以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二十届历次全会精神，认真落实四中全会部署，全面贯彻习近平总书记关于树立和践行正确政绩观的重要论述，持之以恒推进全面从严治党，以立党为公、为民造福、科学决策、真抓实干为总要求，以一体推进学查改为抓手，教育引导各级党组织和党员、干部坚持实事求是、求真务实，为人民出政绩、以实干出政绩，有效防范和纠治政绩观偏差，坚决有力贯彻落实党中央重大决策部署，完整准确全面贯彻新发展理念，加快构建新发展格局，着力推动高质量发展，创造经得起实践、人民、历史检验的实绩，推动“十五五”开好局、起好步，为以中国式现代化全面推进强国建设、民族复兴伟业提供有力保障。【习思想选择题】党的建设","ex":{"stem":"（单选）中共中央办公厅印发《关于在全党开展树立和践行正确政绩观学习教育的通知》。《通知》指出，经党中央同意，在全党开展树立和践行正确政绩观学习教育。树立和践行正确政绩观的抓手是","opts":[{"k":"A","t":"立党为公、为民造福、科学决策、真抓实干"},{"k":"B","t":"一体推进学查改"},{"k":"C","t":"加快构建新发展格局"},{"k":"D","t":"推动高质量发展"}],"ans":"B"}},{"part":"政治板块","sec":"政治板块","title":"西迁精神（4 月7 日）","stars":2,"date":"4月7日","body":"4 月7 日，习近平总书记给上海交通大学、西安交通大学、西南交通大学、北京交通大学全体师生回信，再次强调传承弘扬“西迁精神”。习近平总书记曾深刻指出：“‘西迁精神’的核心是爱国主义，精髓是听党指挥跟党走，与党和国家、与民族和人民同呼吸、共命运，具有深刻现实意义和历史意义。”把时间拉回20 世纪50 年代，当时，新中国百废待兴，工业根基薄弱。在国家号召下，交通大学主体西迁西安，一大批师生告别了熟悉的城市生活，远赴大西北重新扎根。虽然条件更艰苦、生活更不便，但西迁人用行动创造条件，担当起为国家工业化、为建设西部培养人才的重任，把个人命运与国家发展紧密相连，铸就了“胸怀大局、无私奉献、弘扬传统、艰苦创业”的西迁精神。过去的西迁人，面对的是条件简陋、资源匮乏、从零起步的艰苦环境；如今，我们面对科技“无人区”和“卡脖子”难题，要在更高起点上探索未知，在关键核心技术上实现突破，同样需要“西迁精神”——担当国之所需，不去计较个人得失；下好先手棋，在行动中创造条件。在今天传承弘扬“西迁精神”，更要把这一精神落在现实土壤中，在制度和环境上创造条件，让更多人“愿意来、留得住、干得好”，通过政策引导、平台建设，让投身关键领域更具吸引力。同时，还要打破学科壁垒，推动产学研深度融合，构建起更加重视长期价值的评价体系，让“慢变量”的努力得到应有的回报。1957 年，西安交大校刊上登载了一首《忆江南》：“长安好，建设待支援，十万健儿湖海气，吴侬软语满街喧，何必忆江南！”那个年代的知识分子，以万丈豪情把科学的种子播撒在黄土高原上。近70 年过去了，种子生长成大树，如今早已枝繁叶茂。对“西迁精神”的续写，也在一代又一代人的拼搏奉献中生生不息。【思想道德与法治】中国精神与西迁精神","ex":{"stem":"（单选）西迁人用行动创造条件，担当起为国家工业化、为建设西部培养人才的重任，把个人命运与国家发展紧密相连，铸就了“胸怀大局、无私奉献、弘扬传统、艰苦创业”的西迁精神。西迁精神的核心是","opts":[{"k":"A","t":"爱国主义"},{"k":"B","t":"集体主义"},{"k":"C","t":"改革创新"},{"k":"D","t":"听党指挥跟党走"}],"ans":"A"}},{"part":"政治板块","sec":"政治板块","title":"习近平总书记会见中国国民党主席郑丽文（4 月10 日）","stars":0,"date":"4月10日","body":"中共中央总书记习近平4 月10 日上午在北京会见了郑丽文主席率领的中国国民党访问团。习近平对郑丽文率团来访表示欢迎。他指出，国共两党领导人时隔10 年再次会面，对两党关系、两岸关系发展具有重要意义。两岸同胞同属中华民族，包括台湾同胞在内的各族人民共同缔造了统一的多民族国家，共同书写了辉煌的中国历史，共同创造了灿烂的中华文明，共同培育了伟大的民族精神，也铸就了国土不可分、国家不可乱、民族不可散、文明不可断的共同信念，引领中华民族自强不息、中华文明绵延不断。习近平强调，无论国际形势、台海局势如何变化，中华民族伟大复兴的大趋势不会改变，两岸同胞走亲走近、走到一起的大潮流不会改变。两岸同胞都期盼台海和平安宁，期盼两岸关系改善发展，期盼生活更加美好，这是国共两党不可推卸的责任，也是携手合作的动力。我们愿在坚持“九二共识”、反对“台独”的共同政治基础上，同包括中国国民党在内的台湾各政党、团体和社会各界人士一道，加强交流对话，为两岸谋和平、为同胞谋福祉、为民族谋复兴，把两岸关系的未来牢牢掌握在中国人自己手中。习近平就两岸关系发展提出4 点意见。第一，坚持以正确认同促进心灵契合。两岸同胞同根同源、同文同种、血脉相连，是休戚与共的命运共同体。一家人相处，只要有话好好说、有事多商量，就没有化解不了的矛盾分歧。社会制度不同，不是搞分裂的借口。国共两党、两岸同胞要站稳民族立场，传承弘扬中华文化，坚定对中华民族、中华文化、伟大祖国的认同，增强做堂堂正正中国人的志气骨气底气。第二，坚持以和平发展守护共同家园。大陆和台湾同属一个中国，中国是中华民族的共同家园。两岸同胞要守护好、建设好这个共同家园，根本在于坚持“九二共识”、反对“台独”，核心是认同两岸同属一个中国。家和万事兴。只要是有利于两岸关系和平发展的主张我们都欢迎，只要是有利于两岸关系和平发展的事我们都会尽力去做。“台独”是破坏台海和平的罪魁祸首，我们决不姑息、决不容忍。国共两党、两岸同胞要坚持民族大义，反对“台独”分裂和外来干涉，推动两岸关系和平发展，坚定守护中华民族共同家园。第三，坚持以交流融合增进民生福祉。发展两岸关系的目标，是要让两岸同胞过上更美好的生活。我们将继续秉持两岸一家亲理念，积极为台湾同胞办实事、做好事、解难事。祖国大陆山河壮美、市场广阔，欢迎台湾同胞常回家看看，欢迎台湾青年来大陆交流发展，欢迎台湾农渔产品、优质商品进入大陆千家万户。国共两党、两岸同胞要共同扩大两岸交流交往交融，增进两岸同胞亲情福祉。第四，坚持以团结奋斗实现中华民族伟大复兴。今年是孙中山先生诞辰160 周年，振兴中华、国家统一是他的毕生追求。今天我们已经成功走出一条中国式现代化道路，中华民族伟大复兴势不可挡。我们坚信，会有越来越多台湾同胞正确认识大陆社会制度和发展道路，深刻认识到台湾的发展前途在于强大祖国、台湾同胞的利益福祉系于中华民族伟大复兴。今年是大陆“十五五”开局之年，我们愿同广大台湾同胞共享发展机遇和成果、共同壮大中华民族经济。国共两党要巩固政治互信，保持良性互动，团结两岸同胞，携手共创祖国统一、民族复兴的美好未来。郑丽文表示，两岸人民同为炎黄子孙、同属中华民族，都受中华文化熏陶，都是中国人、一家人，理应携手推进孙中山先生提出的振兴中华。国共两党要坚持“九二共识”、反对“台独”的共同政治基础，加强政治互信，发挥沟通平台功能，致力于维护中华历史、弘扬中华文化，推进两岸民间、基层、经贸、文化等各领域交流合作，支持青年交流发展，增进人民共同福祉，推动两岸关系和平发展，开创两岸关系美好未来，实现中华民族伟大复兴。【时政选择题】两岸关系","ex":{"stem":"（多选）2026 年4 月10 日，中共中央总书记习近平在北京会见了郑丽文主席率领的中国国民党访问团。习近平指出，两岸同胞同属中华民族，包括台湾同胞在内的各族人民共同缔造了统一的多民族国家，共同书写了辉煌的中国历史，共同创造了灿烂的中华文明，共同培育了伟大的民族精神，也铸就了国土不可分、国家不可乱、民族不可散、文明不可断的共同信念，引领中华民族自强不息、中华文明绵延不断。习近平就两岸关系发展提出","opts":[{"k":"A","t":"坚持以正确认同促进心灵契合"},{"k":"B","t":"坚持以和平发展守护共同家园"},{"k":"C","t":"坚持以交流融合增进民生福祉"},{"k":"D","t":"坚持以团结奋斗实现中华民族伟大复兴"}],"ans":"ABCD"}},{"part":"政治板块","sec":"政治板块","title":"《求是》杂志发表习近平总书记重要文章《树立和践行正确政绩观》（4 月16 日）","stars":1,"date":"4月16日","body":"文章强调，政绩观问题是一个根本性问题，关乎立党为公、执政为民。只有不断以良好政绩推动党和国家事业发展、造福人民，才能践行好党的宗旨，也才能完成好党的历史使命。要坚持从实际出发、按规律办事，通过科学决策和实干苦干，创造经得起实践和历史检验、真正造福人民、得到群众公认的业绩。文章指出，树立和践行正确政绩观，起决定性作用的是党性。衡量党性强弱的根本尺子是公、私二字。只有党性坚强、摒弃私心杂念，才能保证政绩观不出偏差。各级领导干部要从实现党的使命任务出发，树立和践行正确政绩观，看自己的思想和行动有没有偏离共产主义远大理想和中国特色社会主义共同理想，有没有背离全心全意为人民服务根本宗旨，有没有游离党的路线方针政策和党中央重大决策部署，有没有脱离国情和本地区本部门实际，以功成不必在我、功成必定有我的精神境界，心无旁骛推进中国式现代化。文章指出，共产党人必须牢记，为民造福是最大政绩。干事业、创政绩，为的是造福人民，不是为了个人升迁得失。谋划推进工作，一定要坚持全心全意为人民服务的根本宗旨，坚持以人民为中心的发展思想，坚持发展为了人民、发展依靠人民、发展成果由人民共享，把好事实事做到群众心坎上。要坚持为人民出政绩、以实干出政绩，不在追求政绩上搞急功近利、弄虚作假、盲目蛮干那一套，杜绝“新官不理旧账”和“形象工程”“政绩工程”。文章强调，高质量发展是全面建设社会主义现代化国家的首要任务，坚持高质量发展要成为领导干部政绩观的重要内容。把完整准确全面贯彻新发展理念、着力推动高质量发展这个要求一级一级落实下去，没有正确政绩观是做不到的。要处理好稳和进、立和破、虚和实、标和本、近和远的关系，坚持底线思维，强化风险意识，自觉把新发展理念贯穿到经济社会发展全过程。文章指出，今年是“十五五”开局之年，地方各级领导班子将陆续换届，通过学习教育推动各级领导班子和领导干部树立和践行正确政绩观，十分重要，很有必要。要把学习教育作为今年党的建设的重要任务，确保取得实效。第一，认认真真、扎扎实实提高思想认识。全党同志特别是各级领导干部要从理论上和实践上深刻认识政绩观对党和国家事业发展的重要性，特别是要对照正反两方面典型，深刻汲取经验教训，提高党性觉悟，以对党和人民高度负责的态度，增强树立和践行正确政绩观的思想自觉和行动自觉。第二，认认真真、扎扎实实整改突出问题。要紧扣贯彻“立党为公、为民造福、科学决策、真抓实干”总要求，一体推进学查改，把问题查清、找准，精准务实抓整改。第三，认认真真、扎扎实实立好制度规矩。要从这次学习教育查改的问题中发现制度漏洞、短板、弱项，切实把制度规矩补齐立好，把什么能干、什么不能干、为了谁干、应当怎样干搞得清清楚楚，并且配套完善问责办法，让制度硬起来，充分发挥引导激励、规范约束作用。【新思想】坚持以人民为中心","ex":{"stem":"（多选）习近平强调“共产党人必须牢记，为民造福是最大政绩。干事业、创政绩，为的是造福人民，不是为了个人升迁得失。”树立正确的政绩观（）","opts":[{"k":"A","t":"坚持全心全意为人民服务的根本宗旨"},{"k":"B","t":"坚持以人民为中心的发展思想"},{"k":"C","t":"坚持发展为了人民、发展依靠人民、发展成果由人民共享"},{"k":"D","t":"坚持为人民出政绩、以实干出政绩"}],"ans":"ABCD"}},{"part":"政治板块","sec":"政治板块","title":"习近平主持召开中共中央政治局会议（9 月21 日）","stars":0,"date":"9月21日","body":"中共中央政治局9 月21 日召开会议，研究持之以恒推进全面从严治党重大问题。中共中央总书记习近平主持会议。会议强调，持之以恒推进全面从严治党必须坚持马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观，全面贯彻习近平新时代中国特色社会主义思想，深入学习贯彻习近平党建思想，围绕实现党的使命任务，落实新时代党的建设总要求，以党章为根本，坚持党的先锋队性质，坚持党的全面领导和党中央集中统一领导，着眼于提高党的长期执政能力、保持党的先进性和纯洁性、保持党同人民群众的血肉联系，坚持严的基调不动摇，健全全面从严治党体系，以党的政治建设为统领，全面推进党的各方面建设，充分激发全党积极性主动性创造性，不断实现党的自我净化、自我完善、自我革新、自我提高，持续增强党的政治领导力、思想引领力、群众组织力、社会号召力，确保党始终成为走在时代前列、人民衷心拥护、经得起各种风浪考验、朝气蓬勃的马克思主义执政党，始终成为中国特色社会主义事业的坚强领导核心。","ex":{"stem":"（单选）深入学习贯彻习近平党建思想，围绕实现党的使命任务，落实新时代党的建设总要求。全面从严治党起统领作用的建设是","opts":[{"k":"A","t":"政治建设"},{"k":"B","t":"思想建设"},{"k":"C","t":"组织建设"},{"k":"D","t":"制度建设"}],"ans":"A"}},{"part":"政治板块","sec":"政治板块","title":"中国共产党第二十届中央委员会第五次全体会议（10 月26-29 日）","stars":3,"date":"10月26日","body":"中国共产党第二十届中央委员会第五次全体会议，于2026 年10 月26 日至29 日在北京举行。全会听取和讨论了习近平受中央政治局委托所作的工作报告，审议通过了《中共中央关于持之以恒推进全面从严治党若干重大问题的决定》。全会回顾党100 多年来的奋斗历程，在革命、建设、改革中先后把党的建设作为伟大工程、新的伟大工程，党的十八大以来深入推进新时代党的建设新的伟大工程，找到“让人民来监督政府”和“自我革命”两个跳出治乱兴衰历史周期率的答案，这是中国共产党的独特创造，永载马克思主义政党建设史册。全会高度评价新时代全面从严治党取得的伟大成就。新时代全面从严治党开辟了百年大党自我革命新境界，推动党和国家事业取得历史性成就、发生历史性变革，党和人民赢得强党强国的历史主动。全会指出，在新时代管党治党、兴党强党伟大实践中，以习近平同志为核心的党中央围绕建设什么样的长期执政的马克思主义政党、怎样建设长期执政的马克思主义政党的重大时代课题，提出一系列新理念新思想新战略，形成习近平党建思想。这一思想丰富和发展了马克思主义建党学说，是坚持把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合推进党的理论创新的重大成果，是党和人民实践经验和集体智慧的结晶，是习近平新时代中国特色社会主义思想的重要组成部分，为深入推进新时代党的建设新的伟大工程提供了根本遵循和行动指南。全会强调，持之以恒推进全面从严治党遵循的原则是：坚持服务使命任务，坚持以党的政治建设为统领，坚持全面从严，坚持问题导向，坚持守正创新，坚持以上率下，坚持依规治党。全会提出，增强党性是全面从严治党的根本性任务。全会提出，民主集中制是党的根本组织原则和领导制度，贯彻执行民主集中制是全面从严治党的内在要求。全会提出，全面从严治党关键在从严治吏。全会提出，党的各级组织是全面从严治党的主体。全会提出，正风肃纪是全面从严治党的有力举措。全会提出，一体推进不敢腐不能腐不想腐是全面从严治党的重要方略和反腐败斗争的基本方针。全会提出，加强党内法规制度建设是全面从严治党的长远之策、根本之策。全会提出，持之以恒推进全面从严治党，必须进一步完善党和国家监督体系。全会强调，持之以恒推进全面从严治党是全党的共同政治责任。全会号召，全党更加紧密地团结在以习近平同志为核心的党中央周围，全面贯彻习近平新时代中国特色社会主义思想，励精图治、奋发图强，持之以恒推进全面从严治党，不断开创新时代管党治党、兴党强党新局面，团结带领全国各族人民为全面建成社会主义现代化强国、以中国式现代化全面推进中华民族伟大复兴而不懈奋斗。","ex":{"stem":"（材料分析）持之以恒推进全面从严治党的重要意义答案：回顾100 多年来的奋斗历程，中国共产党能够从胜利走向胜利，就在于坚持为中国人民谋幸福、为中华民族谋复兴，在各个历史时期都高度重视管党治党。在革命、建设、改革中先后把党的建设作为伟大工程、新的伟大工程，党的十八大以来深入推进新时代党的建设新的伟大工程，找到“让人民来监督政府”和“自我革命”两个跳出治乱兴衰历史周期率的答案。新时代全面从严治党开辟了百年大党自我革命新境界，推动党和国家事业取得历史性成就、发生历史性变革，党和人民赢得强党强国的历史主动。","opts":[],"ans":""}},{"part":"文化板块","sec":"文化板块","title":"《求是》杂志发表习近平的重要文章《推动全民阅读，建设书香社会》（4 月16 日）","stars":1,"date":"4月16日","body":"4 月16 日出版的第8 期《求是》杂志发表习近平的重要文章《推动全民阅读，建设书香社会》。文章指出，阅读是人类获取知识、启智增慧、培养道德的重要途径，可以让人得到思想启发，树立崇高理想，涵养浩然之气。学史可以看成败、鉴得失、知兴替；学诗可以情飞扬、志高昂、人灵秀；学伦理可以知廉耻、懂荣辱、辨是非。要提倡多读书，建设书香社会，不断提升人民思想境界、增强人民精神力量，中华民族的精神世界就能更加厚重深邃。文章指出，共产党人要把读马克思主义经典、悟马克思主义原理当作一种生活习惯、当作一种精神追求，用经典涵养正气、淬炼思想、升华境界、指导实践。干部要结合工作需要学习，做到干什么学什么、缺什么补什么。要学习马克思主义理论特别是新时代党的创新理论，学习党史、新中国史、改革开放史、社会主义发展史，学习经济、政治、法律、文化、社会、管理、生态、国际等各方面基础性知识，学习同做好本职工作相关的新知识新技能，不断完善履职尽责必备的知识体系。广大青年抓学习，既要惜时如金、孜孜不倦，下一番心无旁骛、静谧自怡的功夫，又要突出主干、择其精要，努力做到又博又专、愈博愈专。文章指出，要发扬“挤”和“钻”的精神，多读书、读好书，从书本中汲取智慧和营养，不能自我感觉良好、不屑学习，不能借口工作太忙、放松学习，不能为了装点门面、应付学习。要沉下心来，贵在持之以恒，重在学懂弄通，不能心浮气躁、浅尝辄止、不求甚解。哪怕一天挤出半小时，即使读几页书，只要坚持下去，必定会积少成多、积沙成塔，积跬步以至千里。数字阅读要和传统阅读结合起来，守住我们的内核和素养。文章指出，要建设全民终身学习的学习型社会、学习型大国，促进人人皆学、处处能学、时时可学，促进人的全面发展。希望广大党员、干部带头读书学习，修身养志，增长才干；希望孩子们养成阅读习惯，快乐阅读，健康成长；希望全社会都参与到阅读中来，形成爱读书、读好书、善读书的浓厚氛围。【马原】质量互变规律","ex":{"stem":"（多选）《求是》杂志发表习近平的重要文章《推动全民阅读，建设书香社会》，习近平强调要发扬“挤”和“钻”的精神，多读书、读好书，从书本中汲取智慧和营养。“哪怕一天挤出半小时，即使读几页书，只要坚持下去，必定会积少成多、积沙成塔，积跬步以至千里。”其中，“积少成多、积沙成塔，积跬步以至千里。”蕴含的哲学道理是","opts":[{"k":"A","t":"量变是质变必要准备"},{"k":"B","t":"质变是量变的必然结果"},{"k":"C","t":"量变和质变是相互渗透的"},{"k":"D","t":"事物发展是前进性与曲折性的统一"}],"ans":"ABC"}},{"part":"文化板块","sec":"文化板块","title":"习近平代表党中央，向全国广大劳动群众致以节日祝贺和诚挚慰问（5 月1 日）","stars":1,"date":"5月1日","body":"在“五一”国际劳动节到来之际，中共中央总书记、国家主席、中央军委主席习近平代表党中央，向全国广大劳动群众致以节日祝贺和诚挚慰问。习近平指出，在中国式现代化新征程上，广大劳动群众紧紧团结在党的周围，奋力拼搏进取，勇于创新创造，为党和国家事业发展作出了重要贡献。习近平强调，今年是中国共产党成立105 周年，是“十五五”开局之年。希望广大劳动群众大力弘扬劳模精神、劳动精神、工匠精神，苦干实干、敬业奉献，在推动经济社会高质量发展中发挥主力军作用、展现主人翁风采。各级党委和政府要切实维护广大劳动群众合法权益，着力解决急难愁盼问题，动员激励广大劳动群众为实现宏伟蓝图而不懈奋斗。【马原】唯物史观","ex":{"stem":"（多选）在“五一”国际劳动节到来之际，习近平总书记强调，希望广大劳动群众在推动经济社会高质量发展中发挥主力军作用、展现主人翁风采。从马克思主义唯物史观的角度看，强调劳动群众是“主力军”的根本依据在于","opts":[{"k":"A","t":"劳动群众是中国特色社会主义事业的领导核心"},{"k":"B","t":"人民群众是社会历史的主体和创造者"},{"k":"C","t":"人民群众是社会物质财富和精神财富的创造者"},{"k":"D","t":"劳动群众的需求是推动社会形态更替的根本动力"}],"ans":"BC"}},{"part":"文化板块","sec":"文化板块","title":"习近平给中国青年五四奖章暨新时代青年先锋奖获奖者代表回信（5 月4 日）","stars":2,"date":"5月4日","body":"在五四青年节到来之际，中共中央总书记、国家主席、中央军委主席习近平给中国青年五四奖章暨新时代青年先锋奖获奖者代表回信，向全国各族青年致以节日祝贺并提出殷切期望。习近平在回信中说，你们牢记党的嘱托，扎根科技创新、乡村振兴、社会服务、卫国戍边等基层一线，以实干担当书写无悔青春，展现了新时代中国青年自信自强、昂扬向上的良好风貌。习近平强调，今年是“十五五”开局之年，青年建功正当其时。希望你们胸怀远大理想，矢志拼搏奋斗，带动广大青年把个人追求融入国家发展大局，立足各自岗位不断创造新业绩，在新征程上贡献青春力量。【思法】理想信念、艰苦奋斗","ex":{"stem":"（多选）在五四青年节到来之际，习近平总书记给中国青年五四奖章暨新时代青年先锋奖获奖者代表回信，希望广大青年胸怀远大理想，矢志拼搏奋斗，把个人追求融入国家发展大局。从理想信念和人生价值的角度看，这启示我们","opts":[{"k":"A","t":"远大理想是青年成长成才的精神支柱和力量源泉"},{"k":"B","t":"实现理想必须通过艰苦奋斗，在实践中将理想转化为现实"},{"k":"C","t":"个人理想只有同国家前途、民族命运相结合才能升华"},{"k":"D","t":"新时代青年应在基层一线、平凡岗位上实干担当、建功立业"}],"ans":"ABCD"}},{"part":"文化板块","sec":"文化板块","title":"中办、国办印发《文化遗产保护传承“十五五”规划》（9 月29 日）","stars":1,"date":"9月29日","body":"近日，中共中央办公厅、国务院办公厅印发《文化遗产保护传承“十五五”规划》，并发出通知，要求各地区各部门结合实际认真贯彻落实。规划指出，文化遗产承载灿烂文明、传承历史文化、维系民族精神，是不可再生、不可替代的宝贵资源；规划依据“十五五”规划纲要编制，对“十五五”时期文化遗产保护传承作出系统部署。规划明确总体要求：坚持以习近平新时代中国特色社会主义思想为指导，深入贯彻党的二十大和二十届历次全会精神，认真落实四中全会部署，全面贯彻习近平文化思想特别是习近平总书记关于文化遗产保护传承的重要论述，坚持党的全面领导，坚持以人民为中心，坚持创造性转化、创新性发展，坚持保护第一、合理利用和最小干预原则，加强统筹协调，深化改革创新，推动文化遗产系统性保护和统一监管。规划提出主要目标：到2030 年，文化遗产资源全面摸清，监管体制基本理顺，法规制度更加健全，人才队伍持续壮大，保护督察有力有效，文化遗产大保护格局基本形成，文化遗产在建设社会主义文化强国中的重要作用充分彰显。规划部署的重点任务主要有：构建文化遗产大保护格局，巩固第四次全国文物普查成果，建立全国文化遗产资源总目录和大数据库；推动制定文化遗产保护法，健全法规制度体系；落实“先调查、后建设”“先考古、后出让”的文物保护前置要求，加强不可移动文物、历史文化名城名镇名村街区和非物质文化遗产分类保护；推进中华文明探源工程、“考古中国”重大项目和夏商文明研究工程；提升博物馆管理服务水平，实施中小博物馆提升计划；推进长城、大运河、长征、黄河、长江国家文化公园建设保护；强化空间规划管控，把历史文化保护线纳入国土空间规划“一张图”；建立文化遗产保护督察制度，依法开展文化遗产保护检察公益诉讼；加强文化遗产学学科建设、科技支撑和人才队伍建设；深化文化遗产国际交流合作，推进流失文物追索返还。规划的印发实施，是贯彻落实习近平文化思想和“十五五”规划纲要的重要举措，有利于推动文化遗产事业高质量发展，守护好中华文脉、坚定文化自信，为以中国式现代化全面推进强国建设、民族复兴伟业提供强大文化力量。【时政选择题】文化自信","ex":{"stem":"（材料分析）《文化遗产保护传承“十五五”规划》提出，坚持保护第一、合理利用和最小干预原则，推动文化遗产系统性保护和统一监管，到2030 年文化遗产大保护格局基本形成。结合材料，说明印发实施该规划的重大意义。答案：①从文化传承看，文化遗产承载灿烂文明、传承历史文化、维系民族精神，是不可再生、不可替代的宝贵资源，印发实施规划有利于守护中华文脉、赓续中华文明，建设中华民族现代文明。②从指导思想看，规划全面贯彻习近平文化思想，坚持创造性转化、创新性发展，推动中华优秀传统文化与现代社会相协调、与当代实践相适应，是“两个结合”在文化遗产领域的具体体现。③从实践要求看，规划推动文化遗产系统性保护和统一监管，构建文化遗产大保护格局，有利于解决保护碎片化、重用轻保、过度商业开发等问题，让文化遗产活起来、融入现代生活。④从目标指向看，规划服务社会主义文化强国建设，为以中国式现代化全面推进强国建设、民族复兴伟业提供强大文化力量。","opts":[],"ans":""}},{"part":"生态文明","sec":"生态文明","title":"两会通过《中华人民共和国生态环境法典》（3 月12 日）","stars":0,"date":"3月12日","body":"编纂生态环境法典的指导思想是：坚持以习近平新时代中国特色社会主义思想为指导，深刻领悟“两个确立”的决定性意义，增强“四个意识”、坚定“四个自信”、做到“两个维护”，深入贯彻落实党的二十大和二十届历次全会精神，坚持党的领导、人民当家作主、依法治国有机统一，紧紧围绕统筹推进“五位一体”总体布局和协调推进“四个全面”战略布局，聚焦建设更加完善的中国特色社会主义法治体系、建设更高水平的社会主义法治国家，总结实践经验，适应时代要求，同步推进高质量发展和高水平保护，对我国现行的污染防治、生态保护、绿色低碳发展等方面的生态环境法律制度机制和规则规范进行全面系统的编订纂修，形成一部以习近平新时代中国特色社会主义思想特别是习近平生态文明思想为引领，具有中国特色、体现时代特点、反映人民意愿、系统规范协调的生态环境法典，为全面建成社会主义现代化强国、实现第二个百年奋斗目标，以中国式现代化全面推进中华民族伟大复兴提供完备的生态环境法治保障。根据说明，法典共5 编、1242 条，各编依次为总则、污染防治、生态保护、绿色低碳发展、法律责任和附则。【时政选择题】生态文明建设","ex":{"stem":"（多选）2026 年两会审议通过《生态环境法典》，将生态保护纳入法治化轨道，将党的十八大以来生态文明建设理论、制度、实践成果以法典化的方式确定下来。这一举措旨在（）","opts":[{"k":"A","t":"完善生态环境法律制度体系"},{"k":"B","t":"建设更高水平的社会主义法治国家"},{"k":"C","t":"提供完备的生态环境法治保障"},{"k":"D","t":"抓住解决生态环境问题的治本之策"}],"ans":"ABC"}},{"part":"生态文明","sec":"生态文明","title":"8 月15 日《中华人民共和国生态环境法典》正式施行（8 月15 日）","stars":0,"date":"8月15日","body":"2026 年8 月15 日，《中华人民共和国生态环境法典》正式施行，标志着我国生态环境保护进入“法典化”治理新阶段。该法典是全球首部以“生态环境”命名的法典，是我国生态文明法治建设的重大标志性成果。法典系统整合了30 多部生态环境法律、100 余件行政法规、1000 多件地方性法规，为实现人与自然和谐共生的现代化筑牢更强法治根基，构建了以“总则—污染防治—生态保护—绿色低碳发展—法律责任”为框架的完整体系，确立了“预防为主、系统治理、生态优先、绿色发展、公众参与、损害担责”的基本原则。法典的颁布实施，是贯彻落实习近平生态文明思想的重大法治实践，为美丽中国建设提供了系统性、整体性、协同性的法治保障。这一立法创新体现了以人民为中心的发展思想，将人民群众对优美生态环境的需要转化为法律权利；彰显了中国特色社会主义法治道路的制度优势，为全球环境治理贡献了中国方案和中国智慧，推动构建人与自然和谐共生的地球家园。【新思想】生态文明建设","ex":{"stem":"（单选题）2026 年8 月15 日，我国《中华人民共和国生态环境法典》正式施行，恰逢第四个全国生态日，标志着我国生态环境保护迈入系统化、法典化、法治化全新阶段。该法典的重大标志性地位是","opts":[{"k":"A","t":"全球首部以“生态环境”命名的法典"},{"k":"B","t":"我国第一部国家级法典"},{"k":"C","t":"全球首部碳中和专项法典"},{"k":"D","t":"我国首部民生领域综合性法典"}],"ans":"A"}}]};
